def _dependency(dep):
    lo = hi = None
    if isinstance(dep, str):
        return dep, lo, hi
    if isinstance(dep, dict):
        name = dep.get('name', dep.get('package'))
        if name is None and len(dep) == 1:
            name, bounds = next(iter(dep.items()))
            if isinstance(bounds, int):
                lo = hi = bounds
            elif isinstance(bounds, (list, tuple)) and len(bounds) == 2:
                lo, hi = bounds
            return name, lo, hi
        if name is None:
            raise ValueError('invalid dependency')
        bounds = dep.get('range', dep.get('versions'))
        if bounds is not None and isinstance(bounds, (list, tuple)) and len(bounds) == 2:
            lo, hi = bounds
        elif 'version' in dep:
            lo = hi = dep['version']
        else:
            lo, hi = dep.get('min'), dep.get('max')
        return name, lo, hi
    if isinstance(dep, (list, tuple)) and dep:
        name = dep[0]
        if len(dep) == 2:
            bounds = dep[1]
            if isinstance(bounds, int):
                lo = hi = bounds
            elif isinstance(bounds, (list, tuple)) and len(bounds) == 2:
                lo, hi = bounds
        elif len(dep) >= 3:
            lo, hi = dep[1], dep[2]
        return name, lo, hi
    raise ValueError('invalid dependency')


def _active(dep, features):
    if isinstance(dep, dict):
        feature = dep.get('feature')
        if feature:
            return feature in features
    return True


def _forbidden(blocked, name, version):
    values = blocked.get(name, ())
    if isinstance(values, (list, tuple, set, frozenset)):
        return version in values
    return version == values


def _acyclic(selected_rows, features):
    graph = {}
    for name, row in selected_rows.items():
        graph[name] = [
            _dependency(dep)[0]
            for dep in row.get('deps', [])
            if _active(dep, features)
        ]

    colors = {}

    def visit(name):
        color = colors.get(name, 0)
        if color == 1:
            return False
        if color == 2:
            return True
        colors[name] = 1
        for target in graph.get(name, []):
            if target in graph and not visit(target):
                return False
        colors[name] = 2
        return True

    return all(visit(name) for name in graph)


def resolve(data):
    packages = data['packages']
    roots = data['roots']
    blocked = data.get('blocked', {})
    pins = data.get('pins', {})
    features = data.get('features', [])
    names = sorted(packages)
    limits = {name: (interval[0], interval[1])
              for name, interval in roots.items()}
    best_score = None
    best_versions = None

    def search(selected_rows, needed, current_limits):
        nonlocal best_score, best_versions
        pending = sorted(needed - selected_rows.keys())
        if not pending:
            if not _acyclic(selected_rows, features):
                return
            score = tuple(selected_rows[name]['version'] if name in selected_rows else -1
                          for name in names)
            if best_score is None or score > best_score:
                best_score = score
                best_versions = {name: row['version']
                                 for name, row in selected_rows.items()}
            return

        name = pending[0]
        if name not in packages:
            return
        lo, hi = current_limits.get(name, (None, None))
        choices = sorted(packages[name], key=lambda row: row['version'], reverse=True)
        for row in choices:
            version = row['version']
            if lo is not None and version < lo:
                continue
            if hi is not None and version > hi:
                continue
            if name in pins and version != pins[name]:
                continue
            if _forbidden(blocked, name, version):
                continue

            next_rows = dict(selected_rows)
            next_rows[name] = row
            next_needed = set(needed)
            next_limits = dict(current_limits)
            valid = True
            for dep in row.get('deps', []):
                if not _active(dep, features):
                    continue
                target, dep_lo, dep_hi = _dependency(dep)
                next_needed.add(target)
                old_lo, old_hi = next_limits.get(target, (None, None))
                new_lo = old_lo if dep_lo is None else dep_lo if old_lo is None else max(old_lo, dep_lo)
                new_hi = old_hi if dep_hi is None else dep_hi if old_hi is None else min(old_hi, dep_hi)
                if new_lo is not None and new_hi is not None and new_lo > new_hi:
                    valid = False
                    break
                next_limits[target] = (new_lo, new_hi)
                if target in next_rows:
                    chosen = next_rows[target]['version']
                    if ((new_lo is not None and chosen < new_lo)
                            or (new_hi is not None and chosen > new_hi)):
                        valid = False
                        break
            if valid:
                search(next_rows, next_needed, next_limits)

    search({}, set(roots), limits)
    if best_versions is None:
        return {'error': 'unsatisfiable'}
    return {'versions': best_versions}

