def _dependency(dep, features):
    if isinstance(dep, str):
        return dep, None
    if isinstance(dep, dict):
        name = dep.get('name', dep.get('package'))
        if name is None:
            return None, None
        feature = dep.get('feature')
        if feature and feature not in features:
            return None, None
        bounds = dep.get('range')
        if bounds is None and ('min' in dep or 'max' in dep):
            bounds = (dep.get('min'), dep.get('max'))
        return name, bounds
    if isinstance(dep, (list, tuple)) and dep:
        name = dep[0]
        if len(dep) == 2:
            bounds = dep[1]
        elif len(dep) >= 3:
            bounds = (dep[1], dep[2])
        else:
            bounds = None
        return name, bounds
    return None, None


def _in_range(version, bounds):
    if bounds is None:
        return True
    if isinstance(bounds, dict):
        low = bounds.get('min')
        high = bounds.get('max')
    else:
        try:
            low, high = bounds
        except (TypeError, ValueError):
            return True
    return (low is None or version >= low) and (high is None or version <= high)


def _is_acyclic(selected, features):
    graph = {}
    for package, row in selected.items():
        graph[package] = []
        for dep in row.get('deps', []):
            name, _ = _dependency(dep, features)
            if name is not None:
                graph[package].append(name)

    state = {}

    def visit(package):
        mark = state.get(package, 0)
        if mark == 1:
            return False
        if mark == 2:
            return True
        state[package] = 1
        for dependency in graph.get(package, []):
            if not visit(dependency):
                return False
        state[package] = 2
        return True

    return all(visit(package) for package in graph)


def resolve(data):
    packages = data.get('packages', {})
    roots = data.get('roots', {})
    blocked = data.get('blocked', {})
    pins = data.get('pins', {})
    features = data.get('features', [])
    names = sorted(packages)
    best = None
    best_score = None

    def search(selected):
        nonlocal best, best_score

        active = set(roots)
        constraints = {name: [bounds] for name, bounds in roots.items()}
        for package, row in selected.items():
            active.add(package)
            for dep in row.get('deps', []):
                dep_name, dep_bounds = _dependency(dep, features)
                if dep_name is None:
                    continue
                active.add(dep_name)
                if dep_bounds is not None:
                    constraints.setdefault(dep_name, []).append(dep_bounds)

        if any(package not in packages for package in active):
            return
        for package, row in selected.items():
            version = row['version']
            if version in blocked.get(package, ()):
                return
            if package in pins and version != pins[package]:
                return
            if any(not _in_range(version, bounds)
                   for bounds in constraints.get(package, [])):
                return

        pending = active - selected.keys()
        if not pending:
            if not _is_acyclic(selected, features):
                return
            score = tuple(selected[name]['version'] if name in selected else -1
                          for name in names)
            if best_score is None or score > best_score:
                best_score = score
                best = {name: selected[name]['version'] for name in sorted(selected)}
            return

        package = min(pending)
        forbidden = blocked.get(package, ())
        options = sorted(packages[package],
                         key=lambda item: item['version'], reverse=True)
        for row in options:
            version = row['version']
            if version in forbidden:
                continue
            if package in pins and version != pins[package]:
                continue
            if all(_in_range(version, bounds)
                   for bounds in constraints.get(package, [])):
                updated = dict(selected)
                updated[package] = row
                search(updated)

    search({})
    if best is None:
        return {'error': 'unsatisfiable'}
    return {'versions': best}

