def _is_acyclic(edges):
    graph = {}
    for source, target in edges:
        graph.setdefault(source, []).append(target)

    state = {}

    def visit(node):
        mark = state.get(node, 0)
        if mark == 1:
            return False
        if mark == 2:
            return True
        state[node] = 1
        for target in graph.get(node, ()):
            if not visit(target):
                return False
        state[node] = 2
        return True

    return all(visit(node) for node in graph)


def resolve(data):
    packages = data.get('packages', {})
    roots = data.get('roots', {})
    features = set(data.get('features', []))
    blocked = data.get('blocked', {})
    pins = data.get('pins', {})
    names = sorted(packages)

    required = {}
    for name, interval in roots.items():
        low, high = interval
        if low > high:
            return {'error': 'unsatisfiable'}
        if name in required:
            old_low, old_high = required[name]
            low, high = max(low, old_low), min(high, old_high)
        if low > high:
            return {'error': 'unsatisfiable'}
        required[name] = (low, high)

    best = None
    best_key = None

    def options(name, interval):
        low, high = interval
        forbidden = set(blocked.get(name, []))
        pinned = pins.get(name)
        result = []
        for index, row in enumerate(packages.get(name, [])):
            version = row['version']
            if low <= version <= high and version not in forbidden:
                if pinned is None or version == pinned:
                    result.append((index, row))
        result.sort(key=lambda item: item[1]['version'], reverse=True)
        return result

    def search(assigned, constraints, edges):
        nonlocal best, best_key

        if best_key is not None:
            upper = tuple(
                assigned[name][1]['version'] if name in assigned else
                max([-1] + [row['version'] for row in packages.get(name, [])])
                for name in names
            )
            if upper <= best_key:
                return

        unresolved = [name for name in constraints if name not in assigned]
        if not unresolved:
            if not _is_acyclic(edges):
                return
            result = {name: value[1]['version'] for name, value in assigned.items()}
            key = tuple(result.get(name, -1) for name in names)
            if best_key is None or key > best_key:
                best, best_key = result, key
            return

        choices = []
        for name in unresolved:
            candidates = options(name, constraints[name])
            if not candidates:
                return
            choices.append((len(candidates), name, candidates))
        _, name, candidates = min(choices, key=lambda item: (item[0], item[1]))

        for index, row in candidates:
            next_assigned = dict(assigned)
            next_assigned[name] = (index, row)
            next_constraints = dict(constraints)
            next_edges = set(edges)
            valid = True

            for dep in row.get('deps', []):
                feature = dep.get('feature')
                if feature and feature not in features:
                    continue
                target = dep['name']
                low, high = dep['min'], dep['max']
                if target in next_constraints:
                    old_low, old_high = next_constraints[target]
                    low, high = max(low, old_low), min(high, old_high)
                if low > high:
                    valid = False
                    break
                next_constraints[target] = (low, high)
                if target in next_assigned:
                    version = next_assigned[target][1]['version']
                    if not low <= version <= high:
                        valid = False
                        break
                next_edges.add((name, target))

            if valid and _is_acyclic(next_edges):
                search(next_assigned, next_constraints, next_edges)

    search({}, required, set())
    if best is None:
        return {'error': 'unsatisfiable'}
    return {'versions': best}

