def resolve(data):
    packages = data["packages"]
    roots = data["roots"]
    blocked = data.get("blocked", {})
    pins = data.get("pins", {})
    features = set(data.get("features", []))
    names = sorted(packages)

    initial_constraints = {name: [bounds] for name, bounds in roots.items()}
    best_versions = None
    best_vector = None

    def satisfies(version, bounds_list):
        return all(low <= version <= high for low, high in bounds_list)

    def active_deps(row):
        for dep in row.get("deps", []):
            feature = dep.get("feature")
            if feature and feature not in features:
                continue
            yield dep

    def is_acyclic(selected_rows):
        edges = {}
        for name, row in selected_rows.items():
            edges[name] = [dep["name"] for dep in active_deps(row)]

        state = {}

        def visit(name):
            mark = state.get(name, 0)
            if mark == 1:
                return False
            if mark == 2:
                return True
            state[name] = 1
            for target in edges.get(name, []):
                if not visit(target):
                    return False
            state[name] = 2
            return True

        return all(visit(name) for name in edges)

    def search(constraints, assigned, selected_rows):
        nonlocal best_versions, best_vector

        pending = sorted(name for name in constraints if name not in assigned)
        if not pending:
            if not is_acyclic(selected_rows):
                return
            vector = tuple(assigned.get(name, -1) for name in names)
            if best_vector is None or vector > best_vector:
                best_vector = vector
                best_versions = dict(assigned)
            return

        name = pending[0]
        if name not in packages:
            return

        for row in packages[name]:
            version = row["version"]
            if version in blocked.get(name, ()):
                continue
            if name in pins and version != pins[name]:
                continue
            if not satisfies(version, constraints[name]):
                continue

            next_constraints = {key: list(value) for key, value in constraints.items()}
            next_assigned = dict(assigned)
            next_assigned[name] = version
            next_rows = dict(selected_rows)
            next_rows[name] = row
            valid = True

            for dep in active_deps(row):
                dep_name = dep["name"]
                if dep_name not in packages:
                    valid = False
                    break
                next_constraints.setdefault(dep_name, []).append(
                    (dep["min"], dep["max"])
                )
                if dep_name in next_assigned and not satisfies(
                    next_assigned[dep_name], next_constraints[dep_name]
                ):
                    valid = False
                    break

            if valid:
                search(next_constraints, next_assigned, next_rows)

    if all(name in packages for name in roots):
        search(initial_constraints, {}, {})

    if best_versions is None:
        return {"error": "unsatisfiable"}
    return {"versions": best_versions}

