    best_versions = None

    constraints = {
        name: [(bounds[0], bounds[1])]
        for name, bounds in roots.items()
    }

    def satisfies(version, ranges):
        return all(minimum <= version <= maximum for minimum, maximum in ranges)

    def allowed(name, version):
        return (
            version not in blocked.get(name, [])
            and (name not in pins or version == pins[name])
        )

    def active_dependencies(row):
        return [
            dependency
            for dependency in row["deps"]
            if not dependency.get("feature") or dependency["feature"] in features
        ]

    def is_acyclic(chosen):
        edges = {
            name: [dependency["name"] for dependency in active_dependencies(row)]
            for name, row in chosen.items()
        }
        state = {}

        def visit(name):
            mark = state.get(name, 0)
            if mark == 1:
                return False
            if mark == 2:
                return True
            state[name] = 1
            for dependency_name in edges.get(name, []):
                if not visit(dependency_name):
                    return False
            state[name] = 2
            return True

        return all(visit(name) for name in edges)

    def search(required, chosen):
        nonlocal best_key, best_versions

        for name, row in chosen.items():
            if not satisfies(row["version"], required[name]):
                return

        pending = sorted(name for name in required if name not in chosen)
        if not pending:
            if not is_acyclic(chosen):
                return
            key = tuple(
                chosen[name]["version"] if name in chosen else -1
                for name in names
            )
            if best_key is None or key > best_key:
                best_key = key
                best_versions = {
                    name: row["version"] for name, row in chosen.items()
                }
            return

        name = pending[0]
        if name not in packages:
            return

        for row in packages[name]:
            version = row["version"]
            if not satisfies(version, required[name]) or not allowed(name, version):
                continue

            next_required = {
                key: ranges.copy() for key, ranges in required.items()
            }
            valid = True
            for dependency in active_dependencies(row):
                dep_name = dependency["name"]
                next_required.setdefault(dep_name, []).append(
                    (dependency["min"], dependency["max"])
                )
                if dep_name in chosen and not satisfies(
                    chosen[dep_name]["version"], next_required[dep_name]
                ):
                    valid = False
                    break
            if not valid:
                continue

            next_chosen = chosen.copy()
            next_chosen[name] = row
            search(next_required, next_chosen)

    search(constraints, {})
    if best_versions is None:
        return {"error": "unsatisfiable"}
    return {"versions": best_versions}

