        for dep in row.get('deps', []):
            feature = dep.get('feature')
            if feature and feature not in features:
                continue
            active.append(dep)
        return active

    def is_acyclic(selected):
        graph = {
            name: [dep['name'] for dep in active_dependencies(row)]
            for name, row in selected.items()
        }
        visiting = set()
        visited = set()

        def visit(name):
            if name in visiting:
                return False
            if name in visited:
                return True
            visiting.add(name)
            for dependency in graph.get(name, []):
                if not visit(dependency):
                    return False
            visiting.remove(name)
            visited.add(name)
            return True

        return all(visit(name) for name in graph)

    def search(selected, required):
        nonlocal best_versions, best_vector

        for name, row in selected.items():
            if not satisfies(row['version'], required.get(name, [])):
                return
            if name in pins and row['version'] != pins[name]:
