    for name, bounds in roots.items():
        constraints.setdefault(name, []).append((bounds[0], bounds[1]))

    def allowed(name, version, limits):
        if version in blocked.get(name, ()):
            return False
        if name in pins and version != pins[name]:
            return False
        return all(low <= version <= high for low, high in limits)

    def options(name, limits):
        rows = [row for row in packages.get(name, ())
                if allowed(name, row["version"], limits)]
        return sorted(rows, key=lambda row: row["version"], reverse=True)

    best_versions = None
    best_score = None

    def search(limits, selected, graph):
        nonlocal best_versions, best_score

        for name, row in selected.items():
            if not allowed(name, row["version"], limits.get(name, ())):
                return

        upper = []
        for name in names:
            if name in selected:
                upper.append(selected[name]["version"])
                continue
            choices = options(name, limits.get(name, ()))
            if name in limits:
                if not choices:
                    return
                upper.append(choices[0]["version"])
            else:
                upper.append(max([-1] + [row["version"] for row in choices]))
        upper = tuple(upper)
        if best_score is not None and upper <= best_score:
            return

        unresolved = [name for name in limits if name not in selected]
        if not unresolved:
            if is_acyclic(graph):
                versions = {name: row["version"] for name, row in selected.items()}
                score = tuple(versions.get(name, -1) for name in names)
                if best_score is None or score > best_score:
                    best_score = score
                    best_versions = versions
            return

        name = min(unresolved)
        for row in options(name, limits.get(name, ())):
            next_selected = dict(selected)
            next_selected[name] = row
            next_limits = {key: list(value) for key, value in limits.items()}
            deps = active_dependencies(row, features)
            next_graph = dict(graph)
            next_graph[name] = {dep["name"] for dep in deps}
            for dep in deps:
                next_limits.setdefault(dep["name"], []).append(
                    (dep["min"], dep["max"])
                )
            search(next_limits, next_selected, next_graph)

    search(constraints, {}, {})
    if best_versions is None:
        return {"error": "unsatisfiable"}
    return {"versions": best_versions}

def active_dependencies(row, features):
    result = []
    for dep in row.get("deps", []):
        feature = dep.get("feature")
        if feature and feature not in features:
