def is_acyclic(graph):
    state = {}

    def visit(node):
        mark = state.get(node, 0)
        if mark == 1:
            return False
        if mark == 2:
            return True
        state[node] = 1
        for child in graph.get(node, ()):
            if not visit(child):
                return False
        state[node] = 2
        return True

    return all(visit(node) for node in graph)

