def resolve(data):
    packages = data["packages"]
    roots = data["roots"]
    blocked = data.get("blocked", {})
    pins = data.get("pins", {})
    features = data.get("features", [])
    names = sorted(packages)

    if any(name not in packages for name in roots):
        return {"error": "unsatisfiable"}

    best_vector = None
    best_versions = None

    def domain(name, bounds):
        low, high = bounds.get(name, (float("-inf"), float("inf")))
        forbidden = blocked.get(name, ())
        pin = pins.get(name)
        return [
            row for row in packages[name]
            if low <= row["version"] <= high
            and row["version"] not in forbidden
            and (pin is None or row["version"] == pin)
        ]

    def acyclic(assigned):
        graph = {name: [] for name in assigned}
        for name, row in assigned.items():
            for dep in row["deps"]:
                feature = dep.get("feature")
                if feature and feature not in features:
                    continue
                graph[name].append(dep["name"])

        visiting = set()
        visited = set()

        def visit(name):
            if name in visiting:
                return False
            if name in visited:
                return True
            visiting.add(name)
            for child in graph[name]:
                if not visit(child):
                    return False
            visiting.remove(name)
            visited.add(name)
            return True

        return all(visit(name) for name in graph)

    def search(selected, assigned, bounds):
        nonlocal best_vector, best_versions

        upper = []
        for name in names:
            if name in assigned:
                upper.append(assigned[name]["version"])
            elif name in selected:
                rows = domain(name, bounds)
                if not rows:
                    return
                upper.append(max(row["version"] for row in rows))
            else:
                upper.append(max([-1] + [row["version"] for row in packages[name]]))
        if best_vector is not None and tuple(upper) <= best_vector:
            return

        pending = [name for name in names if name in selected and name not in assigned]
        if not pending:
            if not acyclic(assigned):
                return
            vector = tuple(
                assigned[name]["version"] if name in assigned else -1
                for name in names
            )
            if best_vector is None or vector > best_vector:
                best_vector = vector
                best_versions = {
                    name: assigned[name]["version"]
                    for name in names if name in assigned
                }
            return

        name = pending[0]
        rows = sorted(
            domain(name, bounds),
            key=lambda row: row["version"],
            reverse=True,
        )
        for row in rows:
            next_selected = set(selected)
            next_assigned = dict(assigned)
            next_bounds = dict(bounds)
            next_assigned[name] = row
            valid = True

            for dep in row["deps"]:
                feature = dep.get("feature")
                if feature and feature not in features:
                    continue

                dep_name = dep["name"]
                if dep_name not in packages:
                    valid = False
                    break

                low, high = dep["min"], dep["max"]
                if dep_name in next_bounds:
                    old_low, old_high = next_bounds[dep_name]
                    low = max(low, old_low)
                    high = min(high, old_high)
                if low > high:
                    valid = False
                    break

                next_bounds[dep_name] = (low, high)
                next_selected.add(dep_name)
                if dep_name in next_assigned:
                    version = next_assigned[dep_name]["version"]
                    if not low <= version <= high:
                        valid = False
                        break

            if valid:
                search(next_selected, next_assigned, next_bounds)

    initial_bounds = {
        name: (interval[0], interval[1])
        for name, interval in roots.items()
    }
    search(set(roots), {}, initial_bounds)

    if best_versions is None:
        return {"error": "unsatisfiable"}
    return {"versions": best_versions}

