    def search(assigned, limits, graph):
        nonlocal best, best_vector
        pending = sorted(name for name in limits if name not in assigned)
        if not pending:
            vector = tuple(assigned.get(name, -1) for name in names)
            if best_vector is None or vector > best_vector:
                best_vector = vector
                best = assigned.copy()
            return

        name = pending[0]
        for row in packages.get(name, []):
            version = row['version']
            if version in blocked.get(name, []):
                continue
            if name in pins and version != pins[name]:
