            next_assigned[name] = version
            next_limits = limits.copy()
            next_graph = {node: edges.copy() for node, edges in graph.items()}
            next_graph.setdefault(name, set())
            valid = True

            for dep in row.get('deps', []):
                feature = dep.get('feature')
                if feature and feature not in features:
                    continue
                target = dep['name']
                if target not in packages:
                    valid = False
                    break
                low, high = dep['min'], dep['max']
                next_limits[target] = next_limits.get(target, []).copy()
                next_limits[target].append((low, high))
                if target in next_assigned and not low <= next_assigned[target] <= high:
                    valid = False
                    break
                next_graph[name].add(target)

            if valid and not has_cycle(next_graph):
                search(next_assigned, next_limits, next_graph)

    search({}, constraints, {})
    if best is None:
        return {'error': 'unsatisfiable'}
    return {'versions': best}

def has_cycle(graph):
    visiting = set()
    visited = set()

    def visit(node):
        if node in visiting:
            return True
        if node in visited:
            return False
        visiting.add(node)
        for neighbor in graph.get(node, ()):
            if visit(neighbor):
                return True
        visiting.remove(node)
        visited.add(node)
        return False

    return any(visit(node) for node in graph)

