def resolve(data):
    packages = data.get('packages', {})
    roots = data.get('roots', {})
    blocked = data.get('blocked', {})
    pins = data.get('pins', {})
    features = set(data.get('features', []))
    names = sorted(packages)

    # Constraints are inclusive (minimum, maximum) pairs for installed packages.
    initial_constraints = {
        name: [tuple(interval)] for name, interval in roots.items()
    }
    maximum = {
        name: max([-1] + [row['version'] for row in rows])
        for name, rows in packages.items()
    }
    best_versions = None
    best_vector = None

    def valid_version(name, version, constraints):
        if version in blocked.get(name, []):
            return False
        if name in pins and version != pins[name]:
            return False
        return all(low <= version <= high for low, high in constraints)

    def acyclic(assignment):
        graph = {}
        for name, row in assignment.items():
            edges = []
            for dep in row.get('deps', []):
                feature = dep.get('feature')
                if feature and feature not in features:
                    continue
                edges.append(dep['name'])
            graph[name] = edges

        state = {}

        def visit(name):
            mark = state.get(name, 0)
            if mark == 1:
                return False
            if mark == 2:
                return True
            state[name] = 1
            for target in graph.get(name, []):
                if target not in assignment or not visit(target):
                    return False
            state[name] = 2
            return True

        return all(visit(name) for name in assignment)

    def search(assignment, constraints):
        nonlocal best_versions, best_vector

        # An optimistic vector bounds every completion, including packages
        # that may later enter the dependency closure.
        upper = tuple(
            assignment[name]['version'] if name in assignment else maximum.get(name, -1)
            for name in names
        )
        if best_vector is not None and upper <= best_vector:
            return

        pending = [name for name in constraints if name not in assignment]
        if not pending:
            if not acyclic(assignment):
                return
            vector = tuple(assignment[name]['version'] if name in assignment else -1
                           for name in names)
            if best_vector is None or vector > best_vector:
                best_vector = vector
                best_versions = {name: assignment[name]['version'] for name in assignment}
            return

        # Choose the most constrained unresolved package; break ties by name.
        choices = []
        for name in pending:
            rows = [row for row in packages.get(name, [])
                    if valid_version(name, row['version'], constraints[name])]
            rows.sort(key=lambda row: row['version'], reverse=True)
            if not rows:
                return
            choices.append((len(rows), name, rows))
        _, name, rows = min(choices, key=lambda item: (item[0], item[1]))

        for row in rows:
            next_assignment = dict(assignment)
            next_assignment[name] = row
            next_constraints = {key: list(value) for key, value in constraints.items()}
            feasible = True
            for dep in row.get('deps', []):
                feature = dep.get('feature')
                if feature and feature not in features:
                    continue
                target = dep['name']
                next_constraints.setdefault(target, []).append((dep['min'], dep['max']))
                if target in next_assignment and not valid_version(
                    target, next_assignment[target]['version'], next_constraints[target]
                ):
                    feasible = False
                    break
            if feasible:
                search(next_assignment, next_constraints)

    search({}, initial_constraints)
    if best_versions is None:
        return {'error': 'unsatisfiable'}
    return {'versions': best_versions}

