            next_selected[name] = row
            next_needed = set(needed)
            next_limits = {pkg: list(ranges) for pkg, ranges in limits.items()}
            valid = True
            for dep in active_dependencies(row, features):
                child = dep['name']
                lo, hi = dep['min'], dep['max']
                next_needed.add(child)
