def resolve(data):
    packages = data.get("packages", {})
    roots = data.get("roots", {})
    blocked = data.get("blocked", {})
    pins = data.get("pins", {})
    features = set(data.get("features", []))
    names = sorted(packages)
    best_vector = None
    best_versions = None

    def row_allowed(name, row, constraints):
        version = row["version"]
        if version in blocked.get(name, ()):
            return False
        if name in pins and version != pins[name]:
            return False
        return all(low <= version <= high for low, high in constraints.get(name, ()))

    def has_cycle(graph):
        visiting = set()
        visited = set()

        def visit(name):
            if name in visiting:
                return True
            if name in visited:
                return False
            visiting.add(name)
            for target in graph.get(name, ()):
                if visit(target):
                    return True
            visiting.remove(name)
            visited.add(name)
            return False

        return any(visit(name) for name in graph)

    def search(assigned, constraints, demanded, graph):
        nonlocal best_vector, best_versions

        # A coordinate-wise optimistic bound lets completed high-priority
        # choices prune branches that cannot improve the current solution.
        upper = []
        for name in names:
            if name in assigned:
                upper.append(assigned[name])
                continue
            rows = packages.get(name, ())
            if name in demanded:
                possible = [r["version"] for r in rows
                            if row_allowed(name, r, constraints)]
            else:
                possible = [r["version"] for r in rows
                            if row_allowed(name, r, {})]
            upper.append(max(possible) if possible else -1)
        upper = tuple(upper)
        if best_vector is not None and upper <= best_vector:
            return

        pending = sorted(demanded - assigned.keys())
        if not pending:
            vector = tuple(assigned.get(name, -1) for name in names)
            if best_vector is None or vector > best_vector:
                best_vector = vector
                best_versions = dict(assigned)
            return

        name = pending[0]
        rows = [r for r in packages.get(name, ())
                if row_allowed(name, r, constraints)]
        rows.sort(key=lambda r: r["version"], reverse=True)
        for row in rows:
            version = row["version"]
            next_assigned = dict(assigned)
            next_assigned[name] = version
            next_constraints = {n: list(ranges) for n, ranges in constraints.items()}
            next_demanded = set(demanded)
            next_graph = {n: set(targets) for n, targets in graph.items()}
            next_graph.setdefault(name, set())
            valid = True

            for dep in row.get("deps", ()):
                feature = dep.get("feature")
                if feature and feature not in features:
                    continue
                target = dep["name"]
                low, high = dep["min"], dep["max"]
                next_constraints.setdefault(target, []).append((low, high))
                next_demanded.add(target)
                next_graph[name].add(target)
                if target in next_assigned and not (
                    low <= next_assigned[target] <= high
                ):
                    valid = False
                    break

            if not valid or has_cycle(next_graph):
                continue
            search(next_assigned, next_constraints, next_demanded, next_graph)

    initial_constraints = {}
    demanded = set()
    for name, interval in roots.items():
        low, high = interval
        initial_constraints.setdefault(name, []).append((low, high))
        demanded.add(name)

    search({}, initial_constraints, demanded, {})
    if best_versions is None:
        return {"error": "unsatisfiable"}
    return {"versions": best_versions}

