        if 'id' in event:
            key = ('id', event['id'])
        else:
            key = ('anonymous', position)

        revision = event.get('revision', 0)
        current = winners.get(key)
        if current is None or revision >= current[0]:
            winners[key] = (revision, position, event)

    balances = dict(data.get('opening', {}))
    for _, _, event in sorted(winners.values(), key=lambda winner: winner[1]):
        if event.get('void', False):
            continue

        account = event.get('account', 'default')
        currency = event.get('currency', 'USD')
        key = f'{account}|{currency}'
        balances.setdefault(key, 0)
        balances[key] += amount(event, data['rounding'])

    return {'balances': balances}

def _round_basis_points(numerator, mode):
    if mode == 'half_up':
        return (numerator + 5000) // 10000
    return numerator // 10000


def amount(e, mode):
    base = e['price'] * e.get('quantity', 1)
    discount_bp = max(0, min(10000, e.get('discount_bp', 0)))

    net = _round_basis_points(base * (10000 - discount_bp), mode)
    tax = _round_basis_points(net * e.get('tax_bp', 0), mode)
    result = net + tax

    if e.get('kind') == 'refund':
        result = -result
    return result

from rules import active_dependencies, candidates, is_acyclic


def solve(data):
    packages = data.get('packages', {})
    roots = data.get('roots', {})
    blocked = data.get('blocked', {})
    pins = data.get('pins', {})
    features = set(data.get('features', []))
    names = sorted(packages)

    constraints = {name: [tuple(interval)] for name, interval in roots.items()}
    best_score = None
    best_versions = None

    def search(selected, required):
        nonlocal best_score, best_versions

        # An optimistic lexicographic bound lets us skip branches that cannot
        # improve the best complete installation found so far.
        for name in required:
            if name not in selected and not candidates(
                name, packages, required, blocked, pins
            ):
                return

        upper = []
        for name in names:
            if name in selected:
                upper.append(selected[name]['version'])
            elif name in required:
                options = candidates(name, packages, required, blocked, pins)
                if not options:
                    return
                upper.append(max(row['version'] for row in options))
            else:
                options = candidates(name, packages, {}, blocked, pins)
                upper.append(max([-1] + [row['version'] for row in options]))
        upper = tuple(upper)
        if best_score is not None and upper <= best_score:
            return

        unresolved = [name for name in required if name not in selected]
        if not unresolved:
            if not is_acyclic(selected, features):
                return
            score = tuple(selected[name]['version'] if name in selected else -1
                          for name in names)
            if best_score is None or score > best_score:
                best_score = score
                best_versions = {
                    name: selected[name]['version'] for name in selected
                }
            return

        name = min(unresolved)
        for row in candidates(name, packages, required, blocked, pins):
            next_selected = dict(selected)
            next_selected[name] = row
            next_required = {key: list(value) for key, value in required.items()}
            valid = True
            for dep in active_dependencies(row, features):
                dep_name = dep['name']
                intervals = next_required.setdefault(dep_name, [])
                intervals.append((dep['min'], dep['max']))
                if dep_name in next_selected:
                    version = next_selected[dep_name]['version']
                    if not all(low <= version <= high for low, high in intervals):
                        valid = False
                        break
            if valid:
                search(next_selected, next_required)

    search({}, constraints)
    if best_versions is None:
        return {'error': 'unsatisfiable'}
    return {'versions': best_versions}

def candidates(name, packages, constraints, blocked, pins):
    forbidden = set(blocked.get(name, []))
    pin_present = name in pins
    pin = pins.get(name)
    result = []
    for row in packages.get(name, []):
        version = row['version']
        if version in forbidden:
            continue
        if pin_present and version != pin:
            continue
        if all(low <= version <= high
               for low, high in constraints.get(name, [])):
            result.append(row)
    return sorted(result, key=lambda row: row['version'], reverse=True)


def active_dependencies(row, features):
    return [dep for dep in row.get('deps', [])
            if not dep.get('feature') or dep['feature'] in features]


def is_acyclic(selected, features):
    graph = {}
    for name, row in selected.items():
        deps = active_dependencies(row, features)
        graph[name] = [dep['name'] for dep in deps]
        if any(target not in selected for target in graph[name]):
            return False

    state = {}

    def visit(name):
        if state.get(name) == 1:
            return False
        if state.get(name) == 2:
            return True
        state[name] = 1
        for target in graph[name]:
            if not visit(target):
                return False
        state[name] = 2
        return True

    return all(visit(name) for name in graph)

