def solve_versions(packages, roots, blocked=None, pins=None, features=None):
    if blocked is None:
        blocked = {}
    if pins is None:
        pins = {}
    if features is None:
        features = []

    package_names = sorted(packages)
    best_versions = None
    best_score = None

    def satisfies(version, ranges):
        return all(minimum <= version <= maximum for minimum, maximum in ranges)

    def active_dependencies(row):
        for dependency in row.get("deps", ()):
            feature = dependency.get("feature")
            if feature and feature not in features:
                continue
            yield dependency

    def is_acyclic(selected):
        state = {}

        def visit(name):
            current = state.get(name, 0)
            if current == 1:
                return False
            if current == 2:
                return True
            state[name] = 1
            row = next(
                row for row in packages[name]
                if row["version"] == selected[name]
            )
            for dependency in active_dependencies(row):
                if not visit(dependency["name"]):
                    return False
            state[name] = 2
            return True

        return all(visit(name) for name in selected)

    def visit(selected, required, constraints):
        nonlocal best_versions, best_score

        pending = sorted(required - selected.keys())
        if not pending:
            if not is_acyclic(selected):
                return
            score = tuple(selected.get(name, -1) for name in package_names)
            if best_score is None or score > best_score:
                best_score = score
                best_versions = dict(selected)
            return

        name = pending[0]
        forbidden = blocked.get(name, ())
        for row in packages.get(name, ()):
            version = row["version"]
            if version in forbidden or not satisfies(version, constraints.get(name, ())):
                continue
            if name in pins and version != pins[name]:
                continue

            next_selected = dict(selected)
            next_selected[name] = version
            next_required = set(required)
            next_constraints = {key: list(value) for key, value in constraints.items()}
            valid = True

            for dependency in active_dependencies(row):
                dep_name = dependency["name"]
                dep_range = (dependency["min"], dependency["max"])
                next_required.add(dep_name)
                next_constraints.setdefault(dep_name, []).append(dep_range)
                if dep_name in next_selected and not satisfies(
                    next_selected[dep_name], next_constraints[dep_name]
                ):
                    valid = False
                    break

            if valid:
                visit(next_selected, next_required, next_constraints)

    root_constraints = {
        name: [(minimum, maximum)] for name, (minimum, maximum) in roots.items()
    }
    visit({}, set(roots), root_constraints)

    if best_versions is None:
        return None
    return {name: best_versions[name] for name in sorted(best_versions)}

from rules import active_dependencies, allowed


def solve(data):
    packages = data.get('packages', {})
    roots = data.get('roots', {})
    names = sorted(packages)
    features = set(data.get('features', []))
    blocked = data.get('blocked', {})
    pins = data.get('pins', {})
    best = [None, None]

    constraints = {name: [tuple(bounds)] for name, bounds in roots.items()}
    required = set(roots)

    def has_path(graph, start, goal):
        todo = [start]
        seen = set()
        while todo:
            node = todo.pop()
            if node == goal:
                return True
            if node in seen:
                continue
            seen.add(node)
            todo.extend(graph.get(node, ()))
        return False

    def search(assignments, expanded, limits, graph, needed):
        pending = sorted(needed - expanded)
        if not pending:
            score = tuple(assignments[n]['version'] if n in assignments else -1
                          for n in names)
            if best[0] is None or score > best[0]:
                best[0] = score
                best[1] = dict(assignments)
            return

        name = pending[0]
        if name not in assignments:
            rows = packages.get(name, [])
            candidates = sorted(rows, key=lambda row: row['version'], reverse=True)
            for row in candidates:
                version = row['version']
                if not allowed(name, version, limits, blocked, pins):
                    continue
                child_assignments = dict(assignments)
                child_assignments[name] = row
                search(child_assignments, set(expanded),
                       {key: list(value) for key, value in limits.items()},
                       {key: set(value) for key, value in graph.items()},
                       set(needed))
            return

        row = assignments[name]
        deps = active_dependencies(row.get('deps', []), features)
        new_limits = {key: list(value) for key, value in limits.items()}
        new_needed = set(needed)
        new_graph = {key: set(value) for key, value in graph.items()}
        new_graph.setdefault(name, set())

        for dep in deps:
            target = dep['name']
            low, high = dep['min'], dep['max']
            new_limits.setdefault(target, []).append((low, high))
            new_needed.add(target)
            if target in assignments and not all(
                    lo <= assignments[target]['version'] <= hi
                    for lo, hi in new_limits[target]):
                return
            if target == name or has_path(new_graph, target, name):
                return
            new_graph[name].add(target)

        new_expanded = set(expanded)
        new_expanded.add(name)
        search(dict(assignments), new_expanded, new_limits, new_graph, new_needed)

    search({}, set(), constraints, {}, required)
    if best[1] is None:
        return {'error': 'unsatisfiable'}
    return {'versions': {name: row['version'] for name, row in best[1].items()}}

def active_dependencies(deps, features):
    return [dep for dep in deps
            if not dep.get('feature') or dep.get('feature') in features]


def allowed(name, version, constraints, blocked, pins):
    if version in blocked.get(name, []):
        return False
    if name in pins and version != pins[name]:
        return False
    return all(low <= version <= high
               for low, high in constraints.get(name, []))

