def solve(data):
    packages = data.get('packages', {})
    roots = data.get('roots', {})
    blocked = data.get('blocked', {})
    pins = data.get('pins', {})
    features = data.get('features', [])

    names = set(packages) | set(roots)
    for rows in packages.values():
        for row in rows:
            for dep in row.get('deps', []):
                names.add(dep['name'])
    ordered_names = sorted(names)
    best_vector = None
    best_versions = None

    requirements = {name: tuple(bounds) for name, bounds in roots.items()}
    if any(low > high for low, high in requirements.values()):
        return {'error': 'unsatisfiable'}

    def search(req, chosen, graph):
        nonlocal best_vector, best_versions

        if all(name in chosen for name in req):
            vector = tuple(chosen.get(name, -1) for name in ordered_names)
            if best_vector is None or vector > best_vector:
                best_vector = vector
                best_versions = dict(chosen)
            return

        name = min(n for n in req if n not in chosen)
        low, high = req[name]
        rows = choose(packages.get(name, []), low, high,
                      blocked.get(name, []), pins.get(name))

        for row in rows:
            version = row['version']
            next_req = dict(req)
            next_chosen = dict(chosen)
            next_graph = {n: list(edges) for n, edges in graph.items()}
            next_chosen[name] = version
            next_graph.setdefault(name, [])
            valid = True

            for dep in row.get('deps', []):
                feature = dep.get('feature')
                if feature and feature not in features:
                    continue
                child = dep['name']
                dep_low, dep_high = dep['min'], dep['max']
                if child in next_req:
                    old_low, old_high = next_req[child]
                    dep_low = max(dep_low, old_low)
                    dep_high = min(dep_high, old_high)
                if dep_low > dep_high:
                    valid = False
                    break
                next_req[child] = (dep_low, dep_high)
                if child in next_chosen and not (dep_low <= next_chosen[child] <= dep_high):
                    valid = False
                    break
                if _has_path(next_graph, child, name):
                    valid = False
                    break
                next_graph[name].append(child)

            if valid:
                search(next_req, next_chosen, next_graph)

    search(requirements, {}, {})
    if best_versions is None:
        return {'error': 'unsatisfiable'}
    return {'versions': best_versions}


def _has_path(graph, start, target):
    pending = [start]
    visited = set()
    while pending:
        node = pending.pop()
        if node == target:
            return True
        if node in visited:
            continue
        visited.add(node)
        pending.extend(graph.get(node, []))
    return False

def choose(rows, low=None, high=None, blocked=(), pin=None):
    result = []
    forbidden = set(blocked)
    for row in rows:
        version = row['version']
        if low is not None and version < low:
            continue
        if high is not None and version > high:
            continue
        if version in forbidden:
            continue
        if pin is not None and version != pin:
            continue
        result.append(row)
    return sorted(result, key=lambda row: row['version'], reverse=True)

