        def visit(node):
            if node in visiting:
                return True
            if node in visited:
                return False
            visiting.add(node)
            for target in graph.get(node, ()):
                if visit(target):
                    return True
            visiting.remove(node)
            visited.add(node)
            return False

        return any(visit(node) for node in graph)

    def search(assigned, needed, ranges, graph):
        nonlocal best_vector, best_versions

        pending = needed - assigned.keys()
        if not pending:
            vector = tuple(assigned[name]["version"] if name in assigned else -1 for name in names)
            if best_vector is None or vector > best_vector:
                best_vector = vector
                best_versions = {name: row["version"] for name, row in assigned.items()}
            return

        name = min(pending)
        allowed = ranges.get(name, [])
        forbidden = blocked.get(name, ())
        pin = pins.get(name)
        rows = sorted(packages.get(name, ()), key=lambda row: row["version"], reverse=True)

        for row in rows:
            version = row["version"]
            if not within(version, allowed):
                continue
            if version in forbidden or (pin is not None and version != pin):
                continue

            next_assigned = dict(assigned)
            next_assigned[name] = row
            next_needed = set(needed)
            next_ranges = {key: list(value) for key, value in ranges.items()}
            next_graph = {key: list(value) for key, value in graph.items()}
            edges = []
            valid = True

            for dep in row.get("deps", ()):
                feature = dep.get("feature")
                if feature and feature not in features:
                    continue
                target = dep["name"]
                bound = (dep["min"], dep["max"])
                next_needed.add(target)
                next_ranges.setdefault(target, []).append(bound)
                if target in next_assigned and not within(next_assigned[target]["version"], next_ranges[target]):
                    valid = False
                    break
                edges.append(target)

            if not valid:
                continue
            next_graph[name] = edges
            if has_cycle(next_graph):
                continue
            search(next_assigned, next_needed, next_ranges, next_graph)

    search({}, required, constraints, {})
    if best_versions is None:
        return {"error": "unsatisfiable"}
    return {"versions": best_versions}

from rules import allows, intersect, is_acyclic


def solve(data):
    packages = data['packages']
    roots = data['roots']
    blocked = data.get('blocked', {})
    pins = data.get('pins', {})
    features = set(data.get('features', []))
    names = sorted(packages)

    constraints = {}
    for name, bounds in roots.items():
        constraints[name] = tuple(bounds)
        if bounds[0] > bounds[1]:
            return {'error': 'unsatisfiable'}

    best = None
    best_vector = None

    def search(versions, pending, bounds, graph):
        nonlocal best, best_vector
        pending = pending - set(versions)

        if not pending:
            if not is_acyclic(graph):
                return
            vector = tuple(versions.get(name, -1) for name in names)
            if best_vector is None or vector > best_vector:
                best = dict(versions)
                best_vector = vector
            return

        name = min(pending)
        rows = packages.get(name, [])
        if not rows:
            return

        for row in rows:
            version = row['version']
            if version in blocked.get(name, []):
                continue
            if name in pins and version != pins[name]:
                continue
            if not allows(version, bounds.get(name)):
                continue

            next_bounds = dict(bounds)
            next_pending = pending - {name}
            selected = dict(versions)
            selected[name] = version
            active_deps = []
            feasible = True

            for dep in row.get('deps', []):
                feature = dep.get('feature')
                if feature and feature not in features:
                    continue

                dep_name = dep['name']
                dep_bounds = intersect(
                    next_bounds.get(dep_name), dep['min'], dep['max']
                )
                if dep_bounds[0] > dep_bounds[1]:
                    feasible = False
                    break
                next_bounds[dep_name] = dep_bounds
                if dep_name in selected and not allows(
                    selected[dep_name], dep_bounds
                ):
                    feasible = False
                    break
                next_pending.add(dep_name)
                active_deps.append(dep_name)

            if feasible:
                next_graph = {node: set(edges) for node, edges in graph.items()}
                next_graph[name] = set(active_deps)
                search(selected, next_pending, next_bounds, next_graph)

    search({}, set(roots), constraints, {})
    if best is None:
        return {'error': 'unsatisfiable'}
    return {'versions': best}

def intersect(bounds, minimum, maximum):
    if bounds is None:
        return minimum, maximum
    return max(bounds[0], minimum), min(bounds[1], maximum)


def allows(version, bounds):
    return bounds is None or bounds[0] <= version <= bounds[1]


def is_acyclic(graph):
    state = {}

    def visit(node):
        mark = state.get(node, 0)
        if mark == 1:
            return False
        if mark == 2:
            return True

        state[node] = 1
        for neighbor in graph.get(node, ()):
            if not visit(neighbor):
                return False
        state[node] = 2
        return True

    for node in graph:
        if not visit(node):
            return False
    return True

