        if not pending:
            graph = {}
            for name, row in assigned.items():
                graph[name] = [dep['name'] for dep in active_dependencies(row, features)]
            if not is_acyclic(graph):
                return
            vector = tuple(assigned[name]['version'] if name in assigned else -1 for name in names)
            if best_vector is None or vector > best_vector:
                best_vector = vector
                best_versions = {name: row['version'] for name, row in assigned.items()}
            return

        name = pending[0]
        for row in candidates(name, limits[name]):
            next_assigned = dict(assigned)
            next_assigned[name] = row
            next_limits = {key: list(value) for key, value in limits.items()}
            valid = True
            for dep in active_dependencies(row, features):
                target = dep['name']
                next_limits.setdefault(target, []).append((dep['min'], dep['max']))
                if target in next_assigned:
                    version = next_assigned[target]['version']
                    if not all(low <= version <= high for low, high in next_limits[target]):
                        valid = False
                        break
            if valid:
                search(next_assigned, next_limits)

    search({}, constraints)
    if best_versions is None:
        return {'error': 'unsatisfiable'}
    return {'versions': best_versions}

def active_dependencies(row, features):
    result = []
    for dep in row.get('deps', []):
        feature = dep.get('feature')
        if feature and feature not in features:
            continue
        result.append(dep)
    return result


def is_acyclic(graph):
    state = {}

    def visit(name):
        mark = state.get(name, 0)
        if mark == 1:
            return False
        if mark == 2:
            return True
        state[name] = 1
        for target in graph.get(name, []):
            if not visit(target):
                return False
        state[name] = 2
        return True

    return all(visit(name) for name in graph)

