def resolve(data):
    packages = data.get("packages", {})
    names = sorted(packages)
    roots = data.get("roots", {})
    blocked = data.get("blocked", {})
    pins = data.get("pins", {})
    features = set(data.get("features", []))
    best_vector = None
    best_versions = None

    # Constraints are accumulated as inclusive intervals for each selected name.
    bounds = {name: [tuple(interval)] for name, interval in roots.items()}
    selected = set(roots)

    def has_cycle(edges, assigned):
        state = {}

        def visit(name):
            mark = state.get(name, 0)
            if mark == 1:
                return True
            if mark == 2:
                return False
            state[name] = 1
            for child in edges.get(name, ()):
                if child in assigned and visit(child):
                    return True
            state[name] = 2
            return False

        return any(visit(name) for name in assigned if state.get(name, 0) == 0)

    def search(assigned, chosen, limits, edges):
        nonlocal best_vector, best_versions
        pending = sorted(chosen - assigned.keys())
        if not pending:
            if has_cycle(edges, assigned):
                return
            vector = tuple(assigned[name] if name in assigned else -1 for name in names)
            if best_vector is None or vector > best_vector:
                best_vector = vector
                best_versions = dict(assigned)
            return

        name = pending[0]
        rows = packages.get(name, ())
        for row in sorted(rows, key=lambda item: item["version"], reverse=True):
            version = row["version"]
            if any(version < low or version > high for low, high in limits.get(name, ())):
                continue
            if version in blocked.get(name, ()):
                continue
            if name in pins and version != pins[name]:
                continue

            next_assigned = dict(assigned)
            next_assigned[name] = version
            next_chosen = set(chosen)
            next_limits = {key: list(value) for key, value in limits.items()}
            next_edges = {key: list(value) for key, value in edges.items()}
            active_children = []
            valid = True
            for dep in row.get("deps", ()):
                feature = dep.get("feature")
                if feature and feature not in features:
                    continue
                child = dep["name"]
                low, high = dep["min"], dep["max"]
                next_chosen.add(child)
                next_limits.setdefault(child, []).append((low, high))
                if child in next_assigned and not (low <= next_assigned[child] <= high):
                    valid = False
                    break
                if child in blocked and child in packages:
                    # The version itself is checked when the child is assigned.
                    pass
                active_children.append(child)
            if not valid:
                continue
            next_edges[name] = active_children
            search(next_assigned, next_chosen, next_limits, next_edges)

    search({}, selected, bounds, {})
    if best_versions is None:
        return {"error": "unsatisfiable"}
    return {"versions": best_versions}

