def _active(dependency, features):
    feature = dependency.get("feature")
    return not feature or feature in features


def _acyclic(edges, nodes):
    state = {}

    def visit(node):
        mark = state.get(node, 0)
        if mark == 1:
            return False
        if mark == 2:
            return True
        state[node] = 1
        for target in edges.get(node, ()):
            if not visit(target):
                return False
        state[node] = 2
        return True

    return all(visit(node) for node in nodes)


