            next_constraints = {key: list(value) for key, value in constraints.items()}
            next_selected = dict(selected)
            next_selected[name] = row
            next_edges = {key: list(value) for key, value in edges.items()}
            active_names = []
            valid = True
            for dependency in row.get("deps", []):
                if not _active(dependency, features):
                    continue
                target = dependency["name"]
                low, high = dependency["min"], dependency["max"]
                next_constraints.setdefault(target, []).append((low, high))
                active_names.append(target)
                if target in next_selected:
                    target_version = next_selected[target]["version"]
                    if not low <= target_version <= high:
                        valid = False
                        break
            if not valid:
                continue
            next_edges[name] = active_names
            search(next_constraints, next_selected, next_edges)

    search(initial_constraints, {}, {})
    if best_vector is None:
        return {"error": "unsatisfiable"}
    return {"versions": best_versions}

