def resolve(packages, roots, blocked=None, pins=None, features=None):
    blocked = blocked or {}
    pins = pins or {}
    features = set(features or [])
    names = sorted(packages)
    best_score = None
    best_versions = None
    visited = set()

    if any(name not in packages for name in roots):
        return None

    # Each entry is an inclusive (minimum, maximum) interval; None is unbounded.
    required = {
        name: {(bounds[0], bounds[1])}
        for name, bounds in roots.items()
    }

    def satisfies(version, ranges):
        return all(
            (low is None or version >= low)
            and (high is None or version <= high)
            for low, high in ranges
        )

    def parse_dependencies(row):
        deps = row.get("deps", [])
        if not isinstance(deps, list):
            return None
        parsed = []
        for dep in deps:
            if isinstance(dep, str):
                parsed.append((dep, None, None))
            elif isinstance(dep, dict) and isinstance(dep.get("name"), str):
                feature = dep.get("feature")
                if feature:
                    if feature not in features:
                        continue
                parsed.append((dep["name"], dep.get("min"), dep.get("max")))
            else:
                return None
        return parsed

    def is_acyclic(selected):
        graph = {}
        for name, (_, row_index) in selected.items():
            deps = parse_dependencies(packages[name][row_index])
            if deps is None:
                return False
            graph[name] = [dep_name for dep_name, _, _ in deps]

        # Three-color DFS detects directed cycles, including self cycles.
        colors = {}

        def visit(name):
            color = colors.get(name, 0)
            if color == 1:
                return False
            if color == 2:
                return True
            colors[name] = 1
            for target in graph.get(name, ()):
                if not visit(target):
                    return False
            colors[name] = 2
            return True

        return all(visit(name) for name in graph)

    def search(selected, constraints):
        nonlocal best_score, best_versions

        state = (
            tuple(sorted((name, row_index) for name, (_, row_index) in selected.items())),
            frozenset(
                (name, low, high)
                for name, ranges in constraints.items()
                for low, high in ranges
            ),
        )
        if state in visited:
            return
        visited.add(state)

        for name, (version, _) in selected.items():
            if not satisfies(version, constraints.get(name, ())):
                return

        unresolved = [name for name in constraints if name not in selected]
        if not unresolved:
            if not is_acyclic(selected):
                return
            score = tuple(
                selected[name][0] if name in selected else -1
                for name in names
            )
            if best_score is None or score > best_score:
                best_score = score
                best_versions = {
                    name: version for name, (version, _) in selected.items()
                }
            return

        name = min(unresolved)
        if name not in packages:
            return

        candidates = sorted(
            enumerate(packages[name]),
            key=lambda item: item[1]["version"],
            reverse=True,
        )
        forbidden = blocked.get(name, ())
        for row_index, row in candidates:
            version = row["version"]
            if version in forbidden or not satisfies(version, constraints[name]):
                continue
            if name in pins and version != pins[name]:
                continue

            deps = parse_dependencies(row)
            if deps is None:
                continue

            next_selected = dict(selected)
            next_selected[name] = (version, row_index)
            next_constraints = {
                key: set(ranges) for key, ranges in constraints.items()
            }
            for dep_name, low, high in deps:
                next_constraints.setdefault(dep_name, set()).add((low, high))
            search(next_selected, next_constraints)

    search({}, required)
    return best_versions

