def solve(data):
    packages = data['packages']
    roots = data['roots']
    blocked = data.get('blocked', {})
    pins = data.get('pins', {})
    features = data.get('features', [])
    names = sorted(packages)
    max_versions = {
        name: max([-1] + [row['version'] for row in rows])
        for name, rows in packages.items()
    }
    best_versions = None
    best_vector = None

    initial_demands = {name: [(bounds[0], bounds[1])] for name, bounds in roots.items()}

    def search(assigned, demands, graph):
        nonlocal best_versions, best_vector

        optimistic = tuple(
            assigned[name] if name in assigned else max(-1, max_versions[name])
            for name in names
        )
        if best_vector is not None and optimistic <= best_vector:
            return

        pending = sorted(name for name in demands if name not in assigned)
        if not pending:
            if is_acyclic(graph):
                vector = tuple(assigned.get(name, -1) for name in names)
                if best_vector is None or vector > best_vector:
                    best_vector = vector
                    best_versions = dict(assigned)
            return

        name = pending[0]
        rows = sorted(packages.get(name, []), key=lambda row: row['version'], reverse=True)
        constraints = demands[name]
        forbidden = blocked.get(name, [])

        for row in rows:
            version = row['version']
            if version in forbidden or (name in pins and pins[name] != version):
                continue
            if any(version < low or version > high for low, high in constraints):
                continue

            next_assigned = dict(assigned)
            next_assigned[name] = version
            next_demands = {key: list(value) for key, value in demands.items()}
            next_graph = {key: set(value) for key, value in graph.items()}
            edges = set()
            valid = True

            for dep in row.get('deps', []):
                if not active_dependency(dep, features):
                    continue
                target = dep['name']
                low, high = dep['min'], dep['max']
                edges.add(target)
                if target in next_assigned:
                    if not low <= next_assigned[target] <= high:
                        valid = False
                        break
                else:
                    next_demands.setdefault(target, []).append((low, high))

            if not valid:
                continue
            next_graph[name] = edges
            search(next_assigned, next_demands, next_graph)

    search({}, initial_demands, {})
    if best_versions is None:
        return {'error': 'unsatisfiable'}
    return {'versions': best_versions}

