    constraints = {name: [(bounds[0], bounds[1])] for name, bounds in roots.items()}
    best_vector = None
    best_versions = None

    def satisfies(version, ranges):
        return all(low <= version <= high for low, high in ranges)

    def candidates(name, ranges):
        forbidden = blocked.get(name, [])
        pin = pins.get(name)
        rows = [
            row for row in packages.get(name, [])
            if row["version"] not in forbidden
            and (pin is None or row["version"] == pin)
            and satisfies(row["version"], ranges)
        ]
        return sorted(rows, key=lambda row: row["version"], reverse=True)

    def search(assignments, requirements):
        nonlocal best_vector, best_versions
        unresolved = [name for name in requirements if name not in assignments]
        if not unresolved:
            if not is_acyclic(assignments, features):
                return
            vector = tuple(assignments[name]["version"] if name in assignments else -1 for name in names)
            if best_vector is None or vector > best_vector:
                best_vector = vector
                best_versions = {name: assignments[name]["version"] for name in assignments}
            return

        options = []
        for name in unresolved:
            rows = candidates(name, requirements[name])
            if not rows:
                return
            options.append((len(rows), name, rows))
        _, name, rows = min(options, key=lambda item: item[0])

        for row in rows:
            next_assignments = dict(assignments)
            next_assignments[name] = row
            next_requirements = {key: list(value) for key, value in requirements.items()}
            valid = True
            for dep in active_dependencies(row, features):
                target = dep["name"]
                interval = (dep["min"], dep["max"])
                next_requirements.setdefault(target, []).append(interval)
                if target in next_assignments and not satisfies(
                    next_assignments[target]["version"], next_requirements[target]
                ):
                    valid = False
                    break
            if valid:
                search(next_assignments, next_requirements)

    search({}, constraints)
    if best_versions is None:
        return {"error": "unsatisfiable"}
    return {"versions": best_versions}

