    for name, interval in roots.items():
        constraints.setdefault(name, []).append((interval[0], interval[1]))
        demanded.add(name)

    def visit(versions, choices, limits, required):
        nonlocal best_vector, best_versions
        unresolved = sorted(required - versions.keys())
        if not unresolved:
            if not is_acyclic(choices, features):
                return
            vector = tuple(versions.get(name, -1) for name in names)
