                continue
            if any(version < low or version > high for low, high in limits.get(name, [])):
                continue

            next_versions = dict(versions)
            next_versions[name] = version
            next_choices = dict(choices)
            next_choices[name] = row
            next_limits = {key: list(value) for key, value in limits.items()}
            next_required = set(required)
