    visited = set()

    def visit(name):
        if name in visiting:
            return False
        if name in visited:
            return True
        visiting.add(name)
        for dep in graph.get(name, []):
            if dep in graph and not visit(dep):
                return False
        visiting.remove(name)
        visited.add(name)
        return True

    return all(visit(name) for name in graph)


