                next_chosen = dict(chosen)
                next_chosen[name] = row
                search(next_chosen, next_constraints)

    search({}, needed)
    if best_versions is None:
        return {'error': 'unsatisfiable'}
    return {'versions': best_versions}

def _bounds(spec):
    if spec is None:
        return (None, None)
    if isinstance(spec, dict):
        for key in ('range', 'versions'):
            if key in spec:
                return _bounds(spec[key])
        if 'version' in spec:
            return _bounds(spec['version'])
        low = spec.get('min', spec.get('minimum', spec.get('min_version', spec.get('>='))))
        high = spec.get('max', spec.get('maximum', spec.get('max_version', spec.get('<='))))
        if '>' in spec:
            low = spec['>'] + 1
        if '<' in spec:
            high = spec['<'] - 1
        return (low, high)
    if isinstance(spec, (list, tuple)) and len(spec) == 2:
        return (spec[0], spec[1])
    if isinstance(spec, int):
        return (spec, spec)
    return (None, None)


def intersect(left, right):
    a = _bounds(left)
    b = _bounds(right)
    low = b[0] if a[0] is None else a[0] if b[0] is None else max(a[0], b[0])
    high = b[1] if a[1] is None else a[1] if b[1] is None else min(a[1], b[1])
    if low is not None and high is not None and low > high:
        return None
    return (low, high)


def in_range(version, spec):
    low, high = _bounds(spec)
    return (low is None or version >= low) and (high is None or version <= high)


def _dependency(item):
    if isinstance(item, str):
        return [(item, (None, None))]
    if isinstance(item, (list, tuple)) and item:
        name = item[0]
        if not isinstance(name, str):
            return []
        if len(item) == 1:
            spec = None
        elif len(item) == 3 and all(isinstance(x, int) for x in item[1:]):
            spec = (item[1], item[2])
        else:
            spec = item[1]
        return [(name, _bounds(spec))]
    if isinstance(item, dict):
        name_key = next((key for key in ('name', 'package', 'pkg', 'dependency') if key in item), None)
        if name_key is not None:
            name = item[name_key]
            spec = next((item[key] for key in ('range', 'versions', 'version', 'constraint') if key in item), None)
            if spec is None:
                low = item.get('min', item.get('min_version'))
                high = item.get('max', item.get('max_version'))
                spec = (low, high)
            return [(name, _bounds(spec))] if isinstance(name, str) else []
        return [(name, _bounds(spec)) for name, spec in item.items() if isinstance(name, str)]
    return []


def dependencies(items, features=None):
    enabled = features or []
    result = []
    for item in items or []:
        if isinstance(item, dict):
            feature = item.get('feature')
            if feature and feature not in enabled:
                continue
        result.extend(_dependency(item))
    return result

from rules import version_vector


def solve(data):
    packages = data['packages']
    roots = data['roots']
    blocked = data.get('blocked', {})
    pins = data.get('pins', {})
    features = set(data.get('features', []))
    names = sorted(packages)
    best_vector = None
    best_versions = None

    initial_constraints = {
        name: [(bounds[0], bounds[1])] for name, bounds in roots.items()
    }

    def active_dependencies(row):
        return [
            dep for dep in row['deps']
            if not dep.get('feature') or dep['feature'] in features
        ]

    def satisfies(name, version, constraints):
        if not all(low <= version <= high for low, high in constraints):
            return False
        if version in blocked.get(name, ()):
            return False
        if name in pins and version != pins[name]:
            return False
        return True

    def rows_for(name, constraints):
        return sorted(
            (row for row in packages.get(name, [])
             if satisfies(name, row['version'], constraints)),
            key=lambda row: row['version'],
            reverse=True,
        )

    def is_acyclic(selected):
        state = {}

        def visit(name):
            if state.get(name) == 1:
                return False
            if state.get(name) == 2:
                return True
            state[name] = 1
            for dep in active_dependencies(selected[name]):
                dep_name = dep['name']
                if dep_name not in selected or not visit(dep_name):
                    return False
            state[name] = 2
            return True

        return all(visit(name) for name in selected)

    def search(selected, constraints):
        nonlocal best_vector, best_versions

        # Dependencies discovered later can further constrain selected packages.
        for name, row in selected.items():
            if not satisfies(name, row['version'], constraints.get(name, [])):
                return

        pending = set(constraints) - set(selected)
        if not pending:
            if not is_acyclic(selected):
                return
            vector = version_vector(names, selected)
            if best_vector is None or vector > best_vector:
                best_vector = vector
                best_versions = {
                    name: row['version'] for name, row in selected.items()
                }
            return

        # An optimistic bound permits unconstrained packages their best version
        # and constrained packages their best currently valid row.
        if best_vector is not None:
            upper = []
            for name in names:
                if name in selected:
                    upper.append(selected[name]['version'])
                elif name in constraints:
                    options = rows_for(name, constraints[name])
                    upper.append(max((row['version'] for row in options), default=-1))
                else:
                    available = [row['version'] for row in packages.get(name, [])]
                    upper.append(max([-1] + available))
            if tuple(upper) <= best_vector:
                return

        name = min(pending)
        for row in rows_for(name, constraints[name]):
            next_selected = dict(selected)
            next_selected[name] = row
            next_constraints = {
                key: list(value) for key, value in constraints.items()
            }
            for dep in active_dependencies(row):
                dep_name = dep['name']
                next_constraints.setdefault(dep_name, []).append(
                    (dep['min'], dep['max'])
                )
            search(next_selected, next_constraints)

    search({}, initial_constraints)
    if best_versions is None:
        return {'error': 'unsatisfiable'}
    return {'versions': best_versions}

def version_vector(names, selected):
    return tuple(
        selected[name]['version'] if name in selected else -1
        for name in names
    )

