def solve(data):
    cutoff = data.get('cutoff', 10**9)
    winners = {}
    selected = []

    # Apply the cutoff before resolving revisions. Events without an ID are
    # independent, including when their sequence is missing.
    for position, event in enumerate(data['events']):
        if event.get('sequence', 0) > cutoff:
            continue

        if event.get('id') is None:
            selected.append((position, event))
            continue

        key = event['id']
        rank = (event.get('revision', 0), position)
        previous = winners.get(key)
        if previous is None or rank > previous[0]:
            winners[key] = (rank, position, event)

    selected.extend(
        (position, event) for _, position, event in winners.values()
    )
    selected.sort(key=lambda item: item[0])

    balances = dict(data.get('opening', {}))
    rounding = data.get('rounding', 'half_up')
    for _, event in selected:
        if event.get('void') is True:
            continue
        account = event.get('account', 'default')
        currency = event.get('currency', 'USD')
        key = f'{account}|{currency}'
        balances.setdefault(key, 0)
        balances[key] += amount(event, rounding)

    return {'balances': balances}

