def _is_acyclic(graph):
    state = {}

    def visit(name):
        mark = state.get(name, 0)
        if mark == 1:
            return False
        if mark == 2:
            return True
        state[name] = 1
        for dependency in graph.get(name, ()):
            if not visit(dependency):
                return False
        state[name] = 2
        return True

    return all(visit(name) for name in graph)


def solve_versions(data):
    packages = data['packages']
    roots = data['roots']
    blocked = data.get('blocked', {})
    pins = data.get('pins', {})
    features = set(data.get('features', []))
    names = sorted(packages)

    best = None
    best_vector = None

    def search(selected, bounds, pending, graph):
        nonlocal best, best_vector

        bounds = dict(bounds)
        while pending:
            name, low, high = pending.pop()
            if name in bounds:
                old_low, old_high = bounds[name]
                low = max(low, old_low)
                high = min(high, old_high)
            if low > high:
                return
            bounds[name] = (low, high)
            if name in selected and not (low <= selected[name] <= high):
                return

        unresolved = [name for name in bounds if name not in selected]
        if not unresolved:
            if not _is_acyclic(graph):
                return
            vector = tuple(selected.get(name, -1) for name in names)
            if best_vector is None or vector > best_vector:
                best = dict(selected)
                best_vector = vector
            return

        name = min(unresolved)
        low, high = bounds[name]

        for row in packages.get(name, []):
            version = row['version']
            if not (low <= version <= high):
                continue
            if version in blocked.get(name, ()):
                continue
            if name in pins and version != pins[name]:
                continue

            active_deps = []
            for dep in row['deps']:
                feature = dep.get('feature')
                if feature and feature not in features:
                    continue
                active_deps.append(dep)

            next_selected = dict(selected)
            next_selected[name] = version
            next_pending = [
                (dep['name'], dep['min'], dep['max'])
                for dep in active_deps
            ]
            next_graph = dict(graph)
            next_graph[name] = [dep['name'] for dep in active_deps]
            search(next_selected, bounds, next_pending, next_graph)

    initial = [
        (name, interval[0], interval[1])
        for name, interval in roots.items()
    ]
    search({}, {}, initial, {})

    if best is None:
        return {'error': 'unsatisfiable'}
    return {'versions': best}

