def _round(numerator, denominator, mode):
    if mode == 'floor':
        return numerator // denominator
    return (2 * numerator + denominator) // (2 * denominator)


def amount(event, mode):
    gross = event['price'] * event.get('quantity', 1)
    discount_bp = min(10000, max(0, event.get('discount_bp', 0)))
    net = _round(gross * (10000 - discount_bp), 10000, mode)

    tax_bp = event.get('tax_bp', 0)
    tax = _round(net * tax_bp, 10000, mode)
    total = net + tax

    if event.get('kind') == 'refund':
        total = -total
    return total

