def solve(data):
    packages = data.get("packages", {})
    names = sorted(packages)
    features = set(data.get("features", []))
    blocked = data.get("blocked", {})
    pins = data.get("pins", {})

    constraints = {name: tuple(interval) for name, interval in data.get("roots", {}).items()}
    best_score = None
    best_versions = None

    def cyclic(edges):
        state = {}

        def visit(name):
            mark = state.get(name, 0)
            if mark == 1:
                return True
            if mark == 2:
                return False
            state[name] = 1
            for target in edges.get(name, ()):
                if visit(target):
                    return True
            state[name] = 2
            return False

        return any(visit(name) for name in edges if state.get(name, 0) == 0)

    def search(current_constraints, assigned, edges):
        nonlocal best_score, best_versions

        if cyclic(edges):
            return

        upper = []
        for name in names:
            if name in assigned:
                upper.append(assigned[name]["version"])
            elif name in current_constraints:
                options = candidates(
                    packages.get(name, []),
                    current_constraints[name],
                    blocked.get(name, ()),
                    pins[name] if name in pins else None,
                )
                if not options:
                    return
                upper.append(max(row["version"] for row in options))
            else:
                options = candidates(
                    packages.get(name, []),
                    None,
                    blocked.get(name, ()),
                    pins[name] if name in pins else None,
                )
                upper.append(max([-1] + [row["version"] for row in options]))

        if best_score is not None and tuple(upper) <= best_score:
            return

        pending = sorted(name for name in current_constraints if name not in assigned)
        if not pending:
            score = tuple(assigned.get(name, {}).get("version", -1) for name in names)
            if best_score is None or score > best_score:
                best_score = score
                best_versions = {name: row["version"] for name, row in assigned.items()}
            return

        name = pending[0]
        options = candidates(
            packages.get(name, []),
            current_constraints[name],
            blocked.get(name, ()),
            pins[name] if name in pins else None,
        )
        options.sort(key=lambda row: row["version"], reverse=True)

        for row in options:
            next_assigned = dict(assigned)
            next_assigned[name] = row
            next_constraints = dict(current_constraints)
            next_edges = {source: set(targets) for source, targets in edges.items()}
            next_edges.setdefault(name, set())
            valid = True

            for dep in row.get("deps", []):
                feature = dep.get("feature")
                if feature and feature not in features:
                    continue
                target = dep["name"]
                low, high = dep["min"], dep["max"]
                if target in next_constraints:
                    old_low, old_high = next_constraints[target]
                    low, high = max(low, old_low), min(high, old_high)
                next_constraints[target] = (low, high)
                next_edges[name].add(target)
                if target in next_assigned:
                    version = next_assigned[target]["version"]
                    if not low <= version <= high:
                        valid = False
                        break

            if valid:
                search(next_constraints, next_assigned, next_edges)

    search(constraints, {}, {})
    if best_versions is None:
        return {"error": "unsatisfiable"}
    return {"versions": best_versions}

def candidates(rows, bounds=None, blocked=(), pin=None):
    low, high = bounds if bounds is not None else (None, None)
    forbidden = set(blocked)
    result = []
    for row in rows:
        version = row["version"]
        if low is not None and version < low:
            continue
        if high is not None and version > high:
            continue
        if version in forbidden:
            continue
        if pin is not None and version != pin:
            continue
        result.append(row)
    return result

