def solve(data):
    packages = data.get('packages', {})
    roots = data.get('roots', {})
    blocked = data.get('blocked', {})
    pins = data.get('pins', {})
    features = set(data.get('features', []))
    names = sorted(packages)

    constraints = {name: list(bounds) for name, bounds in roots.items()}
    required = set(roots)
    best_score = None
    best_versions = None

    def search(assigned, required_now, limits, graph):
        nonlocal best_score, best_versions

        optimistic = []
        for name in names:
            if name in assigned:
                optimistic.append(assigned[name]['version'])
            else:
                versions = [row['version'] for row in packages.get(name, [])]
                optimistic.append(max([-1] + versions))
        score_bound = tuple(optimistic)
        if best_score is not None and score_bound <= best_score:
            return

        pending = sorted(required_now - assigned.keys())
        if not pending:
            if has_cycle(graph):
                return
            versions = {name: row['version'] for name, row in assigned.items()}
            score = tuple(versions.get(name, -1) for name in names)
            if best_score is None or score > best_score:
                best_score = score
                best_versions = versions
            return

        name = pending[0]
        lo, hi = limits.get(name, [float('-inf'), float('inf')])
        forbidden = set(blocked.get(name, []))
        pin = pins.get(name)
        rows = sorted(packages.get(name, []), key=lambda row: row['version'], reverse=True)
        for row in rows:
            version = row['version']
            if not (lo <= version <= hi):
                continue
            if version in forbidden or (pin is not None and version != pin):
                continue

            next_assigned = dict(assigned)
            next_assigned[name] = row
            next_required = set(required_now)
            next_limits = {key: list(value) for key, value in limits.items()}
            next_graph = {key: set(value) for key, value in graph.items()}
            next_graph.setdefault(name, set())
            valid = True

            for dep in active_dependencies(row, features):
                target = dep['name']
                dep_lo, dep_hi = dep['min'], dep['max']
                current = next_limits.get(target, [float('-inf'), float('inf')])
                merged = [max(current[0], dep_lo), min(current[1], dep_hi)]
                if merged[0] > merged[1]:
                    valid = False
                    break
                next_limits[target] = merged
                next_required.add(target)
                next_graph[name].add(target)
                if target in next_assigned and not (merged[0] <= next_assigned[target]['version'] <= merged[1]):
                    valid = False
                    break

            if valid and not has_cycle(next_graph):
                search(next_assigned, next_required, next_limits, next_graph)

    search({}, required, constraints, {})
    if best_versions is None:
        return {'error': 'unsatisfiable'}
    return {'versions': best_versions}

def active_dependencies(row, features):
    for dep in row.get('deps', []):
        feature = dep.get('feature')
        if feature and feature not in features:
            continue
        yield dep


def has_cycle(graph):
    visiting = set()
    visited = set()

    def visit(node):
        if node in visiting:
            return True
        if node in visited:
            return False
        visiting.add(node)
        for neighbor in graph.get(node, ()):
            if visit(neighbor):
                return True
        visiting.remove(node)
        visited.add(node)
        return False

    return any(visit(node) for node in graph)

