        name: [tuple(bounds)] for name, bounds in roots.items()
    }

    def candidates(name, constraints):
        if name not in packages:
            return []
        forbidden = set(blocked.get(name, []))
        pin = pins.get(name)
        rows = []
        for row in packages[name]:
            version = row['version']
            if version in forbidden or (pin is not None and version != pin):
                continue
            if all(low <= version <= high for low, high in constraints):
                rows.append(row)
        return sorted(rows, key=lambda row: row['version'], reverse=True)

    def is_acyclic(graph):
        state = {}

        def visit(name):
            mark = state.get(name, 0)
            if mark == 1:
                return False
            if mark == 2:
                return True
            state[name] = 1
            for target in graph.get(name, ()):
                if not visit(target):
                    return False
            state[name] = 2
            return True

        return all(visit(name) for name in graph)

    def search(versions, selected_rows, constraints, graph):
        nonlocal best_vector, best_versions

        for name, version in versions.items():
            if not all(low <= version <= high
                       for low, high in constraints.get(name, ())):
                return

        pending = [name for name in constraints if name not in versions]
        if not pending:
            if not is_acyclic(graph):
                return
            vector = tuple(versions.get(name, -1) for name in names)
            if best_vector is None or vector > best_vector:
                best_vector = vector
                best_versions = dict(versions)
            return

        options_by_name = {name: candidates(name, constraints[name])
                           for name in pending}
        if any(not options for options in options_by_name.values()):
            return
        name = min(pending, key=lambda item: (len(options_by_name[item]), item))

        for row in options_by_name[name]:
            version = row['version']
            next_versions = dict(versions)
            next_versions[name] = version
            next_rows = dict(selected_rows)
            next_rows[name] = row
            next_constraints = {key: list(value)
                                for key, value in constraints.items()}
            next_graph = {key: list(value) for key, value in graph.items()}
            edges = []
            for dep in row.get('deps', []):
                feature = dep.get('feature')
                if feature and feature not in features:
                    continue
                target = dep['name']
                next_constraints.setdefault(target, []).append(
                    (dep['min'], dep['max'])
                )
                edges.append(target)
            next_graph[name] = edges
            search(next_versions, next_rows, next_constraints, next_graph)

    search({}, {}, initial_constraints, {})
    if best_versions is None:
        return {'error': 'unsatisfiable'}
    return {'versions': best_versions}

