    blocked = data.get("blocked", {})
    pins = data.get("pins", {})
    features = data.get("features", [])
    names = sorted(packages)

    required = {name: (bounds[0], bounds[1]) for name, bounds in roots.items()}
    best_score = None
    best_versions = None

    def dependencies_for(row):
        active = []
        for dependency in row.get("deps", []):
            if isinstance(dependency, dict):
                feature = dependency.get("feature")
                if feature and feature not in features:
                    continue
                active.append(dependency["name"])
            else:
                active.append(dependency)
        return active

    def is_acyclic(selected_rows):
        graph = {
            name: dependencies_for(row)
            for name, row in selected_rows.items()
        }
        state = {}

        def visit(name):
            mark = state.get(name, 0)
            if mark == 1:
                return False
            if mark == 2:
                return True
            state[name] = 1
            for dependency in graph.get(name, []):
                if dependency in graph and not visit(dependency):
                    return False
            state[name] = 2
            return True

        return all(visit(name) for name in graph)

    def visit(assigned, constraints, selected_rows):
        nonlocal best_score, best_versions

        for name, (lower, upper) in constraints.items():
            if name in assigned and not lower <= assigned[name] <= upper:
                return

        pending = sorted(set(constraints) - set(assigned))
        if not pending:
            if not is_acyclic(selected_rows):
                return
            score = tuple(assigned.get(name, -1) for name in names)
            if best_score is None or score > best_score:
                best_score = score
                best_versions = dict(assigned)
            return

        name = pending[0]
        lower, upper = constraints[name]
        rows = [
            row for row in packages.get(name, [])
            if lower <= row["version"] <= upper
            and row["version"] not in blocked.get(name, [])
            and (name not in pins or row["version"] == pins[name])
        ]

        for row in sorted(rows, key=lambda item: item["version"], reverse=True):
            version = row["version"]
            next_assigned = dict(assigned)
            next_assigned[name] = version
            next_rows = dict(selected_rows)
            next_rows[name] = row
            next_constraints = dict(constraints)
            valid = True

            for dependency in row.get("deps", []):
                if isinstance(dependency, dict):
                    feature = dependency.get("feature")
                    if feature and feature not in features:
                        continue
                    dep_name = dependency["name"]
                    dep_lower = dependency["min"]
                    dep_upper = dependency["max"]
                else:
                    dep_name = dependency
                    dep_lower = float("-inf")
                    dep_upper = float("inf")

                old_lower, old_upper = next_constraints.get(
                    dep_name, (float("-inf"), float("inf"))
                )
                merged_lower = max(old_lower, dep_lower)
                merged_upper = min(old_upper, dep_upper)
                if merged_lower > merged_upper:
                    valid = False
                    break
                next_constraints[dep_name] = (merged_lower, merged_upper)

            if valid:
                visit(next_assigned, next_constraints, next_rows)

    visit({}, required, {})
    if best_versions is None:
        return {"error": "unsatisfiable"}
    return {"versions": best_versions}

from rules import amount


def solve(data):
    cutoff = data.get('cutoff', 10**9)
    events = data.get('events', [])
    selected = {}

    # Filter by sequence before resolving duplicate IDs.
    for position, event in enumerate(events):
        if event.get('sequence', 0) > cutoff:
            continue

        if 'id' in event:
            key = ('id', type(event['id']), event['id'])
        else:
            key = ('anonymous', position)

        revision = event.get('revision', 0)
        previous = selected.get(key)
        if previous is None or revision >= previous[0]:
            selected[key] = (revision, position, event)

    balances = dict(data.get('opening', {}))
    rounding = data.get('rounding', 'half_up')
    for _, _, event in sorted(selected.values(), key=lambda item: item[1]):
        if event.get('void', False):
            continue

        account = event.get('account', 'default')
        currency = event.get('currency', 'USD')
        key = f'{account}|{currency}'
        balances.setdefault(key, 0)
        balances[key] += amount(event, rounding)

    return {'balances': balances}

