def solve(data):
    packages = data.get('packages', {})
    roots = data.get('roots', {})
    blocked = data.get('blocked', {})
    pins = data.get('pins', {})
    features = data.get('features', []) or []

    constraints = {name: [tuple(bounds)] for name, bounds in roots.items()}
    best_score = None
    best_versions = None
    names = sorted(packages)

    def search(selected, limits, edges):
        nonlocal best_score, best_versions

        for name, row in selected.items():
            version = row['version']
            if any(not (lo <= version <= hi) for lo, hi in limits.get(name, [])):
                return
            if version in blocked.get(name, []):
                return
            if name in pins and version != pins[name]:
                return

        pending = [name for name in limits if name not in selected]
        if not pending:
            score = tuple(selected[name]['version'] if name in selected else -1
                          for name in names)
            if best_score is None or score > best_score:
                best_score = score
                best_versions = {name: row['version'] for name, row in selected.items()}
            return

        # The order affects search effort only; every feasible choice is explored.
        name = min(pending)
        if name not in packages:
            return
        pinned = pins.get(name)
        domain = candidates(packages[name], limits.get(name, []),
                            blocked.get(name, []), pinned, name in pins)

        for row in domain:
            version = row['version']
            new_selected = dict(selected)
            new_selected[name] = row
            new_limits = {key: list(value) for key, value in limits.items()}
            new_edges = {key: set(value) for key, value in edges.items()}
            outgoing = new_edges.setdefault(name, set())
            valid = True

            for dep in row.get('deps', []):
                feature = dep.get('feature')
                if feature and feature not in features:
                    continue
                target = dep['name']
                if target not in packages:
                    valid = False
                    break
                new_limits.setdefault(target, []).append((dep['min'], dep['max']))
                outgoing.add(target)
                if target in new_selected:
                    target_version = new_selected[target]['version']
                    if not (dep['min'] <= target_version <= dep['max']):
                        valid = False
                        break

            if valid and acyclic(new_edges):
                search(new_selected, new_limits, new_edges)

    search({}, constraints, {})
    if best_versions is None:
        return {'error': 'unsatisfiable'}
    return {'versions': best_versions}

def candidates(rows, ranges, forbidden, pinned=None, has_pin=False):
    allowed = []
    for row in rows:
        version = row['version']
        if any(not (lo <= version <= hi) for lo, hi in ranges):
            continue
        if version in forbidden:
            continue
        if has_pin and version != pinned:
            continue
        allowed.append(row)
    return sorted(allowed, key=lambda row: row['version'], reverse=True)


def acyclic(edges):
    visiting = set()
    visited = set()

    def visit(node):
        if node in visiting:
            return False
        if node in visited:
            return True
        visiting.add(node)
        for target in edges.get(node, ()):
            if not visit(target):
                return False
        visiting.remove(node)
        visited.add(node)
        return True

    nodes = set(edges)
    for targets in edges.values():
        nodes.update(targets)
    return all(visit(node) for node in nodes)

