def solve(data):
    packages = data['packages']
    roots = data['roots']
    blocked = data.get('blocked', {})
    pins = data.get('pins', {})
    features = set(data.get('features', []))
    names = sorted(packages)

    requirements = {}
    for name, interval in roots.items():
        requirements.setdefault(name, []).append(tuple(interval))

    best_versions = None
    best_vector = None

    def search(installed, required, graph):
        nonlocal best_versions, best_vector

        # Bound this branch using each package's greatest currently possible version.
        upper = []
        for name in names:
            if name in installed:
                upper.append(installed[name])
                continue
            limits = required.get(name, [])
            possible = candidates(
                packages.get(name, []), limits, blocked.get(name, []), pins.get(name)
            )
            if limits and not possible:
                return
            upper.append(max([row['version'] for row in possible] + [-1]))
        if best_vector is not None and tuple(upper) <= best_vector:
            return

        pending = [name for name in required if name not in installed]
        if not pending:
            vector = tuple(installed.get(name, -1) for name in names)
            if best_vector is None or vector > best_vector:
                best_vector = vector
                best_versions = dict(installed)
            return

        # Fixed package-name order and descending versions quickly find strong bounds.
        name = min(pending)
        options = candidates(
            packages.get(name, []), required[name], blocked.get(name, []), pins.get(name)
        )
        for row in options:
            version = row['version']
            next_installed = dict(installed)
            next_installed[name] = version
            next_required = {key: list(value) for key, value in required.items()}
            next_graph = {key: set(value) for key, value in graph.items()}
            next_graph.setdefault(name, set())
            valid = True
            for dep in active_deps(row, features):
                target = dep['name']
                next_required.setdefault(target, []).append((dep['min'], dep['max']))
                next_graph[name].add(target)
                next_graph.setdefault(target, set())
                if target in next_installed:
                    v = next_installed[target]
                    if not dep['min'] <= v <= dep['max']:
                        valid = False
                        break
            if valid and is_acyclic(next_graph):
                search(next_installed, next_required, next_graph)

    search({}, requirements, {})
    if best_versions is None:
        return {'error': 'unsatisfiable'}
    return {'versions': best_versions}

def candidates(rows, intervals, blocked, pin):
    result = []
    for row in rows:
        version = row['version']
        if version in blocked:
            continue
        if pin is not None and version != pin:
            continue
        if all(low <= version <= high for low, high in intervals):
            result.append(row)
    return sorted(result, key=lambda row: row['version'], reverse=True)


def active_deps(row, features):
    active = []
    for dep in row.get('deps', []):
        feature = dep.get('feature')
        if feature and feature not in features:
            continue
        active.append(dep)
    return active


def is_acyclic(graph):
    nodes = set(graph)
    for targets in graph.values():
        nodes.update(targets)
    indegree = {node: 0 for node in nodes}
    for targets in graph.values():
        for target in targets:
            indegree[target] += 1
    ready = [node for node, degree in indegree.items() if degree == 0]
    visited = 0
    while ready:
        node = ready.pop()
        visited += 1
        for target in graph.get(node, ()):
            indegree[target] -= 1
            if indegree[target] == 0:
                ready.append(target)
    return visited == len(nodes)

