def _round_dividend(numerator, mode):
    if mode == "floor":
        return numerator // 10000
    if mode == "half_up":
        return (numerator + 5000) // 10000
    raise ValueError(f"unsupported rounding mode: {mode}")


def amount(event, mode):
    base = event["price"] * event.get("quantity", 1)
    discount_bp = min(10000, max(0, event.get("discount_bp", 0)))
    net = _round_dividend(base * (10000 - discount_bp), mode)
    tax = _round_dividend(net * event.get("tax_bp", 0), mode)
    total = net + tax
    if event.get("kind") == "refund":
        return -total
    return total

def solve(data):
    packages = data.get('packages', {})
    roots = data.get('roots', {})
    names = sorted(packages)
    features = set(data.get('features', []))
    blocked = data.get('blocked', {})
    pins = data.get('pins', {})

    domains = {
        name: list(packages[name])
        for name in names
    }
    constraints = {name: [tuple(bounds)] for name, bounds in roots.items()}
    if any(name not in packages for name in roots):
        return {'error': 'unsatisfiable'}

    best_assignment = None
    best_vector = None
    assignment = {}

    def active_deps(row):
        for dep in row.get('deps', []):
            feature = dep.get('feature')
            if feature and feature not in features:
                continue
            yield dep

    def acyclic(edges):
        state = {}

        def visit(node):
            mark = state.get(node, 0)
            if mark == 1:
                return False
            if mark == 2:
                return True
            state[node] = 1
            for target in edges.get(node, ()):
                if not visit(target):
                    return False
            state[node] = 2
            return True

        return all(visit(node) for node in edges)

    def allowed(name, version, limits):
        if version in blocked.get(name, []):
            return False
        if name in pins and version != pins[name]:
            return False
        return all(lo <= version <= hi for lo, hi in limits)

    def search(i, limits, edges):
        nonlocal best_assignment, best_vector
        if best_vector is not None:
            prefix = tuple(-1 if assignment[n] is None else assignment[n] for n in names[:i])
            if prefix < best_vector[:i]:
                return

        if i == len(names):
            installed = {n for n, v in assignment.items() if v is not None}
            reached = set()
            todo = list(roots)
            while todo:
                node = todo.pop()
                if node in reached:
                    continue
                reached.add(node)
                todo.extend(edges.get(node, ()))
            if reached != installed or not acyclic(edges):
                return
            vector = tuple(-1 if assignment[n] is None else assignment[n] for n in names)
            if best_vector is None or vector > best_vector:
                best_vector = vector
                best_assignment = dict(assignment)
            return

        name = names[i]
        rows = domains[name]
        options = [(row['version'], row) for row in rows]
        # The absent choice has objective value -1.
        options.append((-1, None))
        options.sort(key=lambda item: item[0], reverse=True)

        for _, row in options:
            if row is None:
                if limits.get(name):
                    continue
                assignment[name] = None
                search(i + 1, limits, edges)
                del assignment[name]
                continue

            version = row['version']
            if not allowed(name, version, limits.get(name, ())):
                continue
            new_limits = {n: list(ranges) for n, ranges in limits.items()}
            new_edges = {n: list(targets) for n, targets in edges.items()}
            deps = list(active_deps(row))
            valid = True
            for dep in deps:
                target = dep['name']
                if target not in packages:
                    valid = False
                    break
                bounds = (dep['min'], dep['max'])
                new_limits.setdefault(target, []).append(bounds)
                if target in assignment:
                    chosen = assignment[target]
                    if chosen is None or not allowed(target, chosen, new_limits[target]):
                        valid = False
                        break
                new_edges.setdefault(name, []).append(target)
            if not valid or not acyclic(new_edges):
                continue

            assignment[name] = version
            search(i + 1, new_limits, new_edges)
            del assignment[name]

    search(0, constraints, {})
    if best_assignment is None:
        return {'error': 'unsatisfiable'}
    return {'versions': {name: version for name, version in best_assignment.items() if version is not None}}

