def solve(data):
    return resolve(data)

def resolve(data):
    packages = data['packages']
    roots = data['roots']
    blocked = data.get('blocked', {})
    pins = data.get('pins', {})
    features = set(data.get('features', []))
    names = sorted(packages)
    best_score = None
    best_versions = None

    def active_dependencies(row):
        result = []
        for dep in row.get('deps', []):
            if isinstance(dep, dict):
                feature = dep.get('feature')
                if feature and feature not in features:
                    continue
                result.append((
                    dep['name'],
                    dep.get('min', float('-inf')),
                    dep.get('max', float('inf')),
                ))
            else:
                result.append((dep, float('-inf'), float('inf')))
        return result

    def is_acyclic(chosen):
        graph = {
            name: [dep_name for dep_name, _, _ in active_dependencies(row)]
            for name, row in chosen.items()
        }
        state = {}

        def visit(name):
            mark = state.get(name, 0)
            if mark == 1:
                return False
            if mark == 2:
                return True
            state[name] = 1
            for dependency in graph[name]:
                if not visit(dependency):
                    return False
            state[name] = 2
            return True

        return all(visit(name) for name in graph)

    def search(chosen, pending):
        nonlocal best_score, best_versions

        if not pending:
            if not is_acyclic(chosen):
                return
            score = tuple(
                chosen[name]['version'] if name in chosen else -1
                for name in names
            )
            if best_score is None or score > best_score:
                best_score = score
                best_versions = {
                    name: row['version'] for name, row in chosen.items()
                }
            return

        name, lower, upper = pending[0]
        rest = pending[1:]

        if name not in packages:
            return

        if name in chosen:
            version = chosen[name]['version']
            if lower <= version <= upper:
                search(chosen, rest)
            return

        forbidden = blocked.get(name, [])
        rows = sorted(
            packages[name], key=lambda row: row['version'], reverse=True
        )
        for row in rows:
            version = row['version']
            if not (lower <= version <= upper):
                continue
            if version in forbidden:
                continue
            if name in pins and version != pins[name]:
                continue

            next_chosen = chosen.copy()
            next_chosen[name] = row
            search(next_chosen, rest + active_dependencies(row))

    initial = [
        (name, bounds[0], bounds[1]) for name, bounds in roots.items()
    ]
    search({}, initial)

    if best_versions is None:
        return {'error': 'unsatisfiable'}
    return {'versions': best_versions}

from rules import choose


def _max_bound(a, b):
    if a is None:
        return b
    if b is None:
        return a
    return max(a, b)


def _min_bound(a, b):
    if a is None:
        return b
    if b is None:
        return a
    return min(a, b)


def _active_dependencies(row, features):
    for dep in row.get('deps', []):
        if isinstance(dep, dict):
            feature = dep.get('feature')
            if feature and feature not in features:
                continue
            yield dep
        else:
            yield dep


def _is_acyclic(selected, features):
    graph = {}
    for name, row in selected.items():
        graph[name] = [
            dep['name'] if isinstance(dep, dict) else dep
            for dep in _active_dependencies(row, features)
        ]

    visiting = set()
    visited = set()

    def visit(name):
        if name in visiting:
            return False
        if name in visited:
            return True
        visiting.add(name)
        for dependency in graph.get(name, []):
            if not visit(dependency):
                return False
        visiting.remove(name)
        visited.add(name)
        return True

    return all(visit(name) for name in graph)


def solve(data):
    packages = data['packages']
    names = sorted(packages)
    blocked = data.get('blocked', {})
    pins = data.get('pins', {})
    features = set(data.get('features', []))
    best = None
    best_vector = None

    constraints = {
        name: (bounds[0], bounds[1])
        for name, bounds in data['roots'].items()
    }

    def search(selected, required):
        nonlocal best, best_vector

        for name, row in selected.items():
            low, high = required[name]
            version = row['version']
            if low is not None and version < low:
                return
            if high is not None and version > high:
                return

        pending = sorted(set(required) - set(selected))
        if not pending:
            if not _is_acyclic(selected, features):
                return
            vector = tuple(
                selected[name]['version'] if name in selected else -1
                for name in names
            )
            if best_vector is None or vector > best_vector:
                best_vector = vector
                best = {name: row['version'] for name, row in selected.items()}
            return

        name = pending[0]
        for row in choose(
            packages.get(name, []),
            required[name],
            blocked.get(name, []),
            pins.get(name),
        ):
            next_selected = dict(selected)
            next_selected[name] = row
            next_required = dict(required)

            for dep in _active_dependencies(row, features):
                if isinstance(dep, dict):
                    dep_name = dep['name']
                    dep_low = dep.get('min')
                    dep_high = dep.get('max')
                else:
                    dep_name = dep
                    dep_low = dep_high = None

                old_low, old_high = next_required.get(dep_name, (None, None))
                next_required[dep_name] = (
                    _max_bound(old_low, dep_low),
                    _min_bound(old_high, dep_high),
                )

            search(next_selected, next_required)

    search({}, constraints)
    if best is None:
        return {'error': 'unsatisfiable'}
    return {'versions': best}

def choose(rows, bounds=None, blocked=None, pin=None):
    if bounds is None:
        low, high = None, None
    else:
        low, high = bounds
    forbidden = set(blocked or ())
    return [
        row for row in rows
        if (low is None or row['version'] >= low)
        and (high is None or row['version'] <= high)
        and row['version'] not in forbidden
        and (pin is None or row['version'] == pin)
    ]

from rules import resolve


def solve(data):
    return resolve(data)

def resolve(data):
    packages = data.get("packages", {})
    roots = data.get("roots", {})
    blocked = data.get("blocked", {})
    pins = data.get("pins", {})
    features = data.get("features", [])
    names = sorted(packages)

    def active_deps(row):
        return [
            dep for dep in row.get("deps", [])
            if not dep.get("feature") or dep.get("feature") in features
        ]

    def options(name, constraints):
        result = []
        for row in packages.get(name, []):
            version = row["version"]
            if version in blocked.get(name, []):
                continue
            if name in pins and version != pins[name]:
                continue
            if all(lo <= version <= hi for lo, hi in constraints):
                result.append(row)
        return sorted(result, key=lambda row: row["version"], reverse=True)

    def has_cycle(graph):
        visiting = set()
        visited = set()

        def visit(node):
            if node in visiting:
                return True
            if node in visited:
                return False
            visiting.add(node)
            for target in graph.get(node, ()):
                if visit(target):
                    return True
            visiting.remove(node)
            visited.add(node)
            return False

        return any(visit(node) for node in graph)

    constraints = {name: [tuple(interval)] for name, interval in roots.items()}
    best_vector = None
    best_versions = None
    unrestricted = {}
    for name in names:
        unrestricted[name] = options(name, [])

    def search(constraints, chosen, selected_rows, graph):
        nonlocal best_vector, best_versions

        for name, version in chosen.items():
            if name in constraints and not all(lo <= version <= hi for lo, hi in constraints[name]):
                return

        unresolved = sorted(name for name in constraints if name not in chosen)
        available = {}
        for name in unresolved:
            available[name] = options(name, constraints[name])
            if not available[name]:
                return

        if best_vector is not None:
            upper = []
            for name in names:
                if name in chosen:
                    upper.append(chosen[name])
                elif name in constraints:
                    upper.append(available[name][0]["version"])
                else:
                    versions = unrestricted.get(name, [])
                    upper.append(max(-1, versions[0]["version"]) if versions else -1)
            if tuple(upper) <= best_vector:
                return

        if not unresolved:
            if has_cycle(graph):
                return
            vector = tuple(chosen.get(name, -1) for name in names)
            if best_vector is None or vector > best_vector:
                best_vector = vector
                best_versions = dict(chosen)
            return

        name = unresolved[0]
        for row in available[name]:
            version = row["version"]
            next_chosen = dict(chosen)
            next_chosen[name] = version
            next_rows = dict(selected_rows)
            next_rows[name] = row
            next_constraints = {key: list(value) for key, value in constraints.items()}
            next_graph = {key: list(value) for key, value in graph.items()}
            deps = active_deps(row)
            next_graph[name] = [dep["name"] for dep in deps]
            for dep in deps:
                next_constraints.setdefault(dep["name"], []).append((dep["min"], dep["max"]))
            if not has_cycle(next_graph):
                search(next_constraints, next_chosen, next_rows, next_graph)

    search(constraints, {}, {}, {})
    if best_versions is None:
        return {"error": "unsatisfiable"}
    return {"versions": best_versions}

