                if feature and feature not in features:
                    continue
                child = dep['name']
                next_required.setdefault(child, []).append((dep['min'], dep['max']))
                next_edges[name].append(child)

            search(next_required, next_chosen, next_edges)

    search(required, {}, {})
    if best_versions is None:
        return {'error': 'unsatisfiable'}
    return {'versions': best_versions}

def acyclic(edges):
    state = {}

    def visit(node):
        mark = state.get(node, 0)
        if mark == 1:
            return False
        if mark == 2:
            return True
        state[node] = 1
        for child in edges.get(node, []):
            if not visit(child):
                return False
        state[node] = 2
        return True

    nodes = set(edges)
    for children in edges.values():
        nodes.update(children)
    return all(visit(node) for node in nodes)

