        if lower is not None:
            lo = lower if lo is None else max(lo, lower)
        if upper is not None:
            hi = upper if hi is None else min(hi, upper)
        if lo is not None and hi is not None and lo > hi:
            return False, current
        return True, (lo, hi)

    constraints = {}
    for name, interval in roots.items():
        if name not in packages or not isinstance(interval, (list, tuple)) or len(interval) < 2:
            return {"error": "unsatisfiable"}
        ok, bounds = intersect((None, None), interval[0], interval[1])
        if not ok:
            return {"error": "unsatisfiable"}
        constraints[name] = bounds

    best_versions = None
    best_score = None

    def is_acyclic(selected_rows):
        graph = {
            name: [dep for dep, _, _ in dependency_constraints(row, features)]
            for name, row in selected_rows.items()
        }
        state = {}

        def visit(name):
            mark = state.get(name, 0)
            if mark == 1:
                return False
            if mark == 2:
                return True
            state[name] = 1
            for dependency in graph.get(name, ()):
                if dependency in graph and not visit(dependency):
                    return False
            state[name] = 2
            return True

        return all(visit(name) for name in graph)

    def search(assigned, limits, selected_rows):
        nonlocal best_versions, best_score

        if best_score is not None:
            upper_score = []
            for name in names:
                if name in assigned:
                    upper_score.append(assigned[name])
                else:
                    rows = eligible(name, limits.get(name))
                    upper_score.append(max((row["version"] for row in rows), default=-1))
            if tuple(upper_score) <= best_score:
                return

        pending = set(limits) - set(assigned)
        if not pending:
            if not is_acyclic(selected_rows):
                return
            score = tuple(assigned.get(name, -1) for name in names)
            if best_score is None or score > best_score:
                best_score = score
                best_versions = dict(assigned)
            return

        choices = {}
        for name in pending:
            rows = eligible(name, limits[name])
            if not rows:
                return
            choices[name] = rows
        name = min(pending, key=lambda item: (len(choices[item]), item))

        for row in choices[name]:
            version = row["version"]
            next_assigned = dict(assigned)
            next_assigned[name] = version
            next_selected_rows = dict(selected_rows)
            next_selected_rows[name] = row
            next_limits = dict(limits)
            valid = True

            for dep_name, lower, upper in dependency_constraints(row, features):
                if dep_name not in packages:
                    valid = False
                    break
                current = next_limits.get(dep_name, (None, None))
                ok, bounds = intersect(current, lower, upper)
                if not ok:
                    valid = False
                    break
                if dep_name in next_assigned:
                    dep_version = next_assigned[dep_name]
                    if ((bounds[0] is not None and dep_version < bounds[0]) or
                            (bounds[1] is not None and dep_version > bounds[1])):
                        valid = False
                        break
                next_limits[dep_name] = bounds

            if valid:
                search(next_assigned, next_limits, next_selected_rows)

    search({}, constraints, {})
    if best_versions is None:
        return {"error": "unsatisfiable"}
    return {"versions": {name: best_versions[name] for name in sorted(best_versions)}}

def options(rows, interval=None, blocked=(), pin=None):
    if interval is None:
        lower, upper = None, None
    else:
        lower, upper = interval

    eligible = [
        row for row in rows
        if (lower is None or lower <= row["version"])
        and (upper is None or row["version"] <= upper)
        and row["version"] not in blocked
        and (pin is None or row["version"] == pin)
    ]
    return sorted(eligible, key=lambda row: row["version"], reverse=True)


def dependency_constraints(row, features=()):
    result = []
    for dependency in row.get("deps", []):
        if isinstance(dependency, str):
            result.append((dependency, None, None))
        elif isinstance(dependency, dict):
            feature = dependency.get("feature")
            if feature and feature not in features:
                continue
            name = dependency.get("name", dependency.get("package"))
            if isinstance(name, str):
                result.append((name, dependency.get("min"), dependency.get("max")))
        elif (isinstance(dependency, (list, tuple)) and dependency
              and isinstance(dependency[0], str)):
            lower = dependency[1] if len(dependency) > 1 else None
            upper = dependency[2] if len(dependency) > 2 else None
            result.append((dependency[0], lower, upper))
    return result


def dependencies(row, features=()):
    return {name for name, _, _ in dependency_constraints(row, features)}

