def _matches(version, bounds):
    return all(
        (minimum is None or minimum <= version)
        and (maximum is None or version <= maximum)
        for minimum, maximum in bounds
    )


def _dependency(dependency):
    if isinstance(dependency, str):
        return dependency, (None, None)
    if isinstance(dependency, dict) and "name" in dependency:
        return dependency["name"], (
            dependency.get("min"),
            dependency.get("max"),
        )
    return None


def _has_cycle(graph):
    visiting = set()
    visited = set()

    def visit(name):
        if name in visiting:
            return True
        if name in visited:
            return False
        visiting.add(name)
        for dependency in graph.get(name, ()):
            if visit(dependency):
                return True
        visiting.remove(name)
        visited.add(name)
        return False

    return any(visit(name) for name in graph if name not in visited)


def resolve(data):
    packages = data["packages"]
    blocked = data.get("blocked", {})
    pins = data.get("pins", {})
    features = data.get("features", [])
    names = sorted(packages)
    constraints = {
        name: [tuple(bounds)] for name, bounds in data["roots"].items()
    }
    best_vector = None
    best_versions = None

    def search(assigned, current_constraints, graph):
        nonlocal best_vector, best_versions

        pending = set(current_constraints).difference(assigned)
        if not pending:
            vector = tuple(assigned.get(name, -1) for name in names)
            if best_vector is None or vector > best_vector:
                best_vector = vector
                best_versions = dict(assigned)
            return

        name = min(pending)
        forbidden = blocked.get(name, ())
        for row in packages.get(name, []):
            version = row["version"]
            if version in forbidden or (name in pins and version != pins[name]):
                continue
            if not _matches(version, current_constraints[name]):
                continue

            active_dependencies = []
            parsed_dependencies = []
            valid = True
            for raw_dependency in row.get("deps", []):
                if isinstance(raw_dependency, dict):
                    feature = raw_dependency.get("feature")
                    if feature and feature not in features:
                        continue

                parsed = _dependency(raw_dependency)
                if parsed is None:
                    valid = False
                    break
                dep_name, bounds = parsed
                active_dependencies.append(dep_name)
                parsed_dependencies.append((dep_name, bounds))

            if not valid:
                continue

            next_assigned = dict(assigned)
            next_assigned[name] = version
            next_constraints = {
                package: list(ranges)
                for package, ranges in current_constraints.items()
            }
            for dep_name, bounds in parsed_dependencies:
                next_constraints.setdefault(dep_name, []).append(bounds)
                if dep_name in next_assigned and not _matches(
                    next_assigned[dep_name], next_constraints[dep_name]
                ):
                    valid = False
                    break
            if not valid:
                continue

            next_graph = {package: list(edges) for package, edges in graph.items()}
            next_graph[name] = active_dependencies
            if not _has_cycle(next_graph):
                search(next_assigned, next_constraints, next_graph)

    search({}, constraints, {})
    return best_versions

from rules import options


def solve(data):
    packages = data['packages']
    roots = data['roots']
    blocked = data.get('blocked', {})
    pins = data.get('pins', {})
    features = set(data.get('features', []))
    names = sorted(packages)

    if any(name not in packages for name in roots):
        return {'error': 'unsatisfiable'}

    constraints = {name: tuple(interval) for name, interval in roots.items()}
    best_versions = None
    best_vector = None

    def is_acyclic(assigned, edges):
        state = {}

        def visit(name):
            mark = state.get(name, 0)
            if mark == 1:
                return False
            if mark == 2:
                return True
            state[name] = 1
            for target in edges.get(name, ()):
                if target in assigned and not visit(target):
                    return False
            state[name] = 2
            return True

        return all(visit(name) for name in assigned)

    def search(assigned, required, edges):
        nonlocal best_versions, best_vector

        unresolved = sorted(required.keys() - assigned.keys())
        if not unresolved:
            if not is_acyclic(assigned, edges):
                return
            vector = tuple(
                assigned[name]['version'] if name in assigned else -1
                for name in names
            )
            if best_vector is None or vector > best_vector:
                best_vector = vector
                best_versions = {
                    name: row['version'] for name, row in assigned.items()
                }
            return

        name = unresolved[0]
        low, high = required[name]

        for row in options(
            packages[name], low, high,
            blocked.get(name, ()), pins.get(name)
        ):
            next_assigned = dict(assigned)
            next_assigned[name] = row
            next_required = dict(required)
            next_edges = {key: list(value) for key, value in edges.items()}
            active_edges = []
            feasible = True

            for dep in row.get('deps', []):
                feature = dep.get('feature')
                if feature and feature not in features:
                    continue

                dep_name = dep['name']
                if dep_name not in packages:
                    feasible = False
                    break

                dep_low, dep_high = dep['min'], dep['max']
                if dep_name in next_required:
                    old_low, old_high = next_required[dep_name]
                    dep_low = max(dep_low, old_low)
                    dep_high = min(dep_high, old_high)

                if dep_low > dep_high:
                    feasible = False
                    break

                next_required[dep_name] = (dep_low, dep_high)
                active_edges.append(dep_name)
                if (dep_name in next_assigned and
                        not dep_low <= next_assigned[dep_name]['version'] <= dep_high):
                    feasible = False
                    break

            if feasible:
                next_edges[name] = active_edges
                search(next_assigned, next_required, next_edges)

    search({}, constraints, {})
    if best_versions is None:
        return {'error': 'unsatisfiable'}
    return {'versions': best_versions}

def options(rows, low=None, high=None, blocked=(), pin=None):
    forbidden = set(blocked)
    return sorted(
        (
            row for row in rows
            if (low is None or row['version'] >= low)
            and (high is None or row['version'] <= high)
            and row['version'] not in forbidden
            and (pin is None or row['version'] == pin)
        ),
        key=lambda row: row['version'],
        reverse=True,
    )

