    def visit(name):
        if state.get(name) == 1:
            return False
        if state.get(name) == 2:
            return True
        state[name] = 1
        row = assigned[name]
        for dep_name, _, _ in _dependency_constraints(row, features):
            if dep_name in assigned and not visit(dep_name):
                return False
        state[name] = 2
        return True

    return all(visit(name) for name in assigned)


def resolve(data):
    packages = data['packages']
    roots = data['roots']
    blocked = data.get('blocked', {})
    pins = data.get('pins', {})
    features = set(data.get('features', []))
    names = sorted(packages)
    best_vector = None
    best_versions = None

    initial_constraints = {}
    for name, bounds in roots.items():
        initial_constraints.setdefault(name, []).append((bounds[0], bounds[1]))

    def allowed(name, row, constraints):
        version = row['version']
        return (_within(version, constraints.get(name, [])) and
                version not in blocked.get(name, []) and
                (name not in pins or pins[name] == version))

    def search(assigned, constraints):
        nonlocal best_vector, best_versions

        for name, row in assigned.items():
            if not allowed(name, row, constraints):
                return

        pending = sorted(set(constraints) - set(assigned))
        if not pending:
            if not _acyclic(assigned, features):
                return
            versions = {name: row['version'] for name, row in assigned.items()}
            vector = tuple(versions.get(name, -1) for name in names)
            if best_vector is None or vector > best_vector:
                best_vector = vector
                best_versions = versions
            return

        name = pending[0]
        if name not in packages:
            return

        candidates = [row for row in packages[name]
                      if allowed(name, row, constraints)]
        candidates.sort(key=lambda row: row['version'], reverse=True)

        for row in candidates:
            next_assigned = dict(assigned)
            next_assigned[name] = row
            next_constraints = {key: list(value)
                                for key, value in constraints.items()}
            for dep_name, minimum, maximum in _dependency_constraints(row, features):
                next_constraints.setdefault(dep_name, []).append((minimum, maximum))
            search(next_assigned, next_constraints)

    search({}, initial_constraints)
    if best_versions is None:
        return {'error': 'unsatisfiable'}
    return {'versions': best_versions}

