            for dep in row.get('deps', []):
                feature = dep.get('feature')
                if feature and feature not in features:
                    continue
                target = dep['name']
                low, high = dep['min'], dep['max']
                next_required.setdefault(target, []).append((low, high))
                next_graph[name].append(target)
                if target in next_selected and not (low <= next_selected[target] <= high):
                    valid = False
                    break

            if valid:
                search(next_selected, next_required, next_graph)

    search({}, constraints, {})
    if best_versions is None:
        return {'error': 'unsatisfiable'}
    return {'versions': best_versions}

def has_cycle(graph, selected):
    visiting = set()
    visited = set()

    def visit(name):
        if name in visiting:
            return True
        if name in visited:
            return False
        visiting.add(name)
        for target in graph.get(name, []):
            if target in selected and visit(target):
                return True
        visiting.remove(name)
        visited.add(name)
        return False

    return any(visit(name) for name in selected if name not in visited)

