def _rounded(numerator, mode):
    if mode == 'half_up':
        return (numerator + 5000) // 10000
    return numerator // 10000


def amount(event, mode):
    price_quantity = event['price'] * event.get('quantity', 1)
    discount = min(10000, max(0, event.get('discount_bp', 0)))
    net = _rounded(price_quantity * (10000 - discount), mode)

    tax_bp = event.get('tax_bp', 0)
    total = net + _rounded(net * tax_bp, mode)
    if event.get('kind') == 'refund':
        return -total
    return total

