from rules import candidates


def solve(data):
    packages = data["packages"]
    roots = data["roots"]
    blocked = data.get("blocked", {})
    pins = data.get("pins", {})
    features = set(data.get("features", []))
    names = sorted(packages)
    constraints = {name: tuple(interval) for name, interval in roots.items()}
    best_versions = None
    best_vector = None

    def active_dependency(dependency):
        if isinstance(dependency, str):
            return True
        feature = dependency.get("feature")
        return not feature or feature in features

    def rows_for(name, limits):
        if name not in packages:
            return []
        rows = candidates(packages[name], limits.get(name), blocked.get(name, ()))
        if name in pins:
            rows = [row for row in rows if row["version"] == pins[name]]
        return rows

    def add_interval(limits, name, lower, upper):
        if name in limits:
            old_lower, old_upper = limits[name]
            lower = max(lower, old_lower)
            upper = min(upper, old_upper)
        if lower > upper:
            return False
        limits[name] = (lower, upper)
        return True

    def upper_bound(current, limits):
        bound = []
        for name in names:
            if name in current:
                bound.append(current[name]["version"])
            else:
                versions = [row["version"] for row in rows_for(name, limits)]
                if name in limits:
                    bound.append(max(versions) if versions else float("-inf"))
                else:
                    bound.append(max([-1, *versions]))
        return tuple(bound)

    def is_acyclic(current):
        graph = {name: [] for name in current}
        for name, row in current.items():
            for dependency in row.get("deps", []):
                if not active_dependency(dependency):
                    continue
                dep_name = dependency if isinstance(dependency, str) else dependency["name"]
                graph[name].append(dep_name)

        state = {}

        def visit(name):
            mark = state.get(name, 0)
            if mark == 1:
                return False
            if mark == 2:
                return True
            state[name] = 1
            for neighbor in graph[name]:
                if neighbor not in graph or not visit(neighbor):
                    return False
            state[name] = 2
            return True

        return all(visit(name) for name in graph)

    def search(current, limits):
        nonlocal best_versions, best_vector
        if best_vector is not None and upper_bound(current, limits) <= best_vector:
            return

        pending = sorted(limits.keys() - current.keys())
        if not pending:
            if not is_acyclic(current):
                return
            versions = {name: row["version"] for name, row in current.items()}
            vector = tuple(versions.get(name, -1) for name in names)
            if best_vector is None or vector > best_vector:
                best_vector = vector
                best_versions = versions
            return

        name = pending[0]
        rows = rows_for(name, limits)
        rows.sort(key=lambda row: row["version"], reverse=True)
        for row in rows:
            next_current = dict(current)
            next_current[name] = row
            next_limits = dict(limits)
            valid = True

            for dependency in row.get("deps", []):
                if not active_dependency(dependency):
                    continue
                if isinstance(dependency, str):
                    dep_name = dependency
                    lower, upper = float("-inf"), float("inf")
                else:
                    dep_name = dependency["name"]
                    lower, upper = dependency["min"], dependency["max"]

                if not add_interval(next_limits, dep_name, lower, upper):
                    valid = False
                    break
                if dep_name in next_current:
                    version = next_current[dep_name]["version"]
                    dep_lower, dep_upper = next_limits[dep_name]
                    if not dep_lower <= version <= dep_upper:
                        valid = False
                        break

            if valid:
                search(next_current, next_limits)

    search({}, constraints)
    if best_versions is None:
        return {"error": "unsatisfiable"}
    return {"versions": best_versions}

def candidates(rows, interval=None, blocked=()):
    forbidden = set(blocked)
    if interval is None:
        return [row for row in rows if row["version"] not in forbidden]
    lower, upper = interval
    return [
        row
        for row in rows
        if lower <= row["version"] <= upper and row["version"] not in forbidden
    ]

