        data['packages'],
        data['roots'],
        data.get('blocked', {}),
        data.get('pins', {}),
        data.get('features', []),
    )
    if versions is None:
        return {'error': 'unsatisfiable'}
    return {'versions': versions}

def resolve(packages, roots, blocked=None, pins=None, features=None):
    if blocked is None:
        blocked = {}
    if pins is None:
        pins = {}
    if features is None:
        features = []
    active_features = set(features)

    names = sorted(packages)
    best_score = None
    best_versions = None
    bounds = {name: (limits[0], limits[1]) for name, limits in roots.items()}

    def active_dependencies(row):
        for dependency in row.get('deps', []):
            if isinstance(dependency, dict):
                feature = dependency.get('feature')
                if feature and feature not in active_features:
                    continue
                yield dependency['name'], dependency['min'], dependency['max']
            else:
                yield dependency, float('-inf'), float('inf')

    def is_acyclic(assigned):
        graph = {}
        for name, version in assigned.items():
            row = next(
                row for row in packages.get(name, [])
                if row['version'] == version
            )
            graph[name] = [dep_name for dep_name, _, _ in active_dependencies(row)]

        state = {}

        def visit(name):
            mark = state.get(name, 0)
            if mark == 1:
                return False
            if mark == 2:
                return True
            state[name] = 1
            for dependency in graph.get(name, []):
                if dependency in assigned and not visit(dependency):
                    return False
            state[name] = 2
            return True

        return all(visit(name) for name in graph)

    def search(assigned, current_bounds):
        nonlocal best_score, best_versions

        pending = set(current_bounds) - set(assigned)
        if not pending:
            if not is_acyclic(assigned):
                return
            score = tuple(assigned.get(name, -1) for name in names)
            if best_score is None or score > best_score:
                best_score = score
                best_versions = dict(assigned)
            return

        name = min(pending)
        low, high = current_bounds[name]
        for row in packages.get(name, []):
            version = row['version']
            if version in blocked.get(name, ()):
                continue
            if name in pins and version != pins[name]:
                continue
            if not low <= version <= high:
                continue

            next_assigned = dict(assigned)
            next_assigned[name] = version
            next_bounds = dict(current_bounds)
            valid = True

            for dep_name, dep_low, dep_high in active_dependencies(row):
                old_low, old_high = next_bounds.get(
                    dep_name, (float('-inf'), float('inf'))
                )
                new_low = max(old_low, dep_low)
                new_high = min(old_high, dep_high)
                if new_low > new_high:
                    valid = False
                    break
                next_bounds[dep_name] = (new_low, new_high)

                if dep_name in next_assigned:
                    dep_version = next_assigned[dep_name]
                    if not new_low <= dep_version <= new_high:
                        valid = False
                        break

            if valid:
                search(next_assigned, next_bounds)

    search({}, bounds)
    return best_versions

