from rules import choose


def solve(data):
    packages = data.get('packages', {})
    roots = data.get('roots', {})
    blocked = data.get('blocked', {})
    pins = data.get('pins', {})
    features = data.get('features', [])
    names = sorted(packages)

    if any(name not in packages for name in roots):
        return {'error': 'unsatisfiable'}

    bounds = {name: (interval[0], interval[1])
              for name, interval in roots.items()}
    best_vector = None
    best_versions = None

    def is_acyclic(assigned):
        graph = {}
        for name, row in assigned.items():
            graph[name] = [
                dep['name'] for dep in row.get('deps', [])
                if not dep.get('feature') or dep['feature'] in features
            ]

        state = {}

        def visit(name):
            if state.get(name) == 1:
                return False
            if state.get(name) == 2:
                return True
            state[name] = 1
            for dependency in graph.get(name, []):
                if not visit(dependency):
                    return False
            state[name] = 2
            return True

        return all(visit(name) for name in graph)

    def search(assigned, required, constraints):
        nonlocal best_vector, best_versions

        pending = required - assigned.keys()
        if not pending:
            if not is_acyclic(assigned):
                return
            vector = tuple(assigned[name]['version'] if name in assigned else -1
                           for name in names)
            if best_vector is None or vector > best_vector:
                best_vector = vector
                best_versions = {name: assigned[name]['version']
                                 for name in sorted(assigned)}
            return

        if best_vector is not None:
            upper = []
            for name in names:
                if name in assigned:
                    upper.append(assigned[name]['version'])
                    continue
                low, high = constraints.get(name, (None, None))
                versions = [row['version'] for row in packages[name]
                            if (low is None or row['version'] >= low)
                            and (high is None or row['version'] <= high)
                            and row['version'] not in blocked.get(name, [])]
                upper.append(max([-1] + versions))
            if tuple(upper) <= best_vector:
                return

        name = min(pending)
        low, high = constraints.get(name, (None, None))
        candidates = [row for row in choose(packages.get(name, []))
                      if (low is None or row['version'] >= low)
                      and (high is None or row['version'] <= high)
                      and row['version'] not in blocked.get(name, [])
                      and (name not in pins or row['version'] == pins[name])]

        for row in candidates:
            next_constraints = dict(constraints)
            next_required = set(required)
            valid = True
            for dep in row.get('deps', []):
                feature = dep.get('feature')
                if feature and feature not in features:
                    continue

                dep_name = dep['name']
                dep_low = dep['min']
                dep_high = dep['max']
                if dep_name not in packages:
                    valid = False
                    break
                old_low, old_high = next_constraints.get(dep_name, (None, None))
                new_low = dep_low if old_low is None else max(old_low, dep_low)
                new_high = dep_high if old_high is None else min(old_high, dep_high)
                if new_low > new_high:
                    valid = False
                    break
                next_constraints[dep_name] = (new_low, new_high)
                next_required.add(dep_name)

                if dep_name in assigned:
                    version = assigned[dep_name]['version']
                    if not new_low <= version <= new_high:
                        valid = False
                        break
                elif dep_name == name:
                    if not new_low <= row['version'] <= new_high:
                        valid = False
                        break

            if not valid:
                continue

            next_assigned = dict(assigned)
            next_assigned[name] = row
            search(next_assigned, next_required, next_constraints)

    search({}, set(roots), bounds)
    if best_versions is None:
        return {'error': 'unsatisfiable'}
    return {'versions': best_versions}

def solve(data):
    packages = data.get('packages', {})
    roots = data.get('roots', {})
    blocked = data.get('blocked', {})
    pins = data.get('pins', {})
    features = set(data.get('features', []))
    names = sorted(packages)

    def allowed_rows(name, constraints):
        rows = packages.get(name, [])
        forbidden = blocked.get(name, [])
        pin = pins.get(name)
        return [
            row for row in rows
            if row['version'] not in forbidden
            and (pin is None or row['version'] == pin)
            and all(low <= row['version'] <= high for low, high in constraints)
        ]

    def has_path(edges, start, goal):
        todo = [start]
        seen = set()
        while todo:
            node = todo.pop()
            if node == goal:
                return True
            if node not in seen:
                seen.add(node)
                todo.extend(edges.get(node, ()))
        return False

    constraints = {name: [tuple(interval)] for name, interval in roots.items()}
    if any(not allowed_rows(name, ranges) for name, ranges in constraints.items()):
        return {'error': 'unsatisfiable'}

    best_vector = None
    best_versions = None

    def search(chosen, required, edges):
        nonlocal best_vector, best_versions

        domains = {}
        for name in required:
            if name in chosen:
                version = chosen[name]['version']
                if any(not low <= version <= high for low, high in required[name]):
                    return
            else:
                domain = allowed_rows(name, required[name])
                if not domain:
                    return
                domains[name] = domain

        # An independent upper bound on every component of the objective.
        upper = []
        for name in names:
            if name in chosen:
                upper.append(chosen[name]['version'])
            elif name in domains:
                upper.append(max(row['version'] for row in domains[name]))
            else:
                possible = allowed_rows(name, [])
                upper.append(max((row['version'] for row in possible), default=-1))
        if best_vector is not None and tuple(upper) <= best_vector:
            return

        if not domains:
            vector = tuple(chosen[name]['version'] if name in chosen else -1 for name in names)
            if best_vector is None or vector > best_vector:
                best_vector = vector
                best_versions = {name: chosen[name]['version'] for name in sorted(chosen)}
            return

        # Minimum remaining values keeps constraint-heavy searches small.
        name = min(domains, key=lambda n: (len(domains[n]), n))
        for row in sorted(domains[name], key=lambda r: r['version'], reverse=True):
            next_chosen = dict(chosen)
            next_chosen[name] = row
            next_required = {n: list(ranges) for n, ranges in required.items()}
            next_edges = {n: set(targets) for n, targets in edges.items()}
            next_edges.setdefault(name, set())
            valid = True
            for dep in row.get('deps', []):
                feature = dep.get('feature')
                if feature and feature not in features:
                    continue
                target = dep['name']
                if has_path(next_edges, target, name):
                    valid = False
                    break
                next_edges[name].add(target)
                next_required.setdefault(target, []).append((dep['min'], dep['max']))
                if target in next_chosen:
                    version = next_chosen[target]['version']
                    if not dep['min'] <= version <= dep['max']:
                        valid = False
                        break
                elif not allowed_rows(target, next_required[target]):
                    valid = False
                    break
            if valid:
                search(next_chosen, next_required, next_edges)

    search({}, constraints, {})
    if best_versions is None:
        return {'error': 'unsatisfiable'}
    return {'versions': best_versions}

