def solve_packages(data):
    packages = data.get('packages', {})
    roots = data.get('roots', {})
    blocked = data.get('blocked', {})
    pins = data.get('pins', {})
    features = set(data.get('features', []))
    names = sorted(packages)
    best_vector = None
    best_versions = None

    def active_deps(row):
        for dep in row.get('deps', []):
            feature = dep.get('feature')
            if feature and feature not in features:
                continue
            yield dep

    def acyclic(assignment):
        graph = {}
        for name, row in assignment.items():
            graph[name] = [dep['name'] for dep in active_deps(row)]

        colors = {}

        def visit(name):
            color = colors.get(name, 0)
            if color == 1:
                return False
            if color == 2:
                return True
            colors[name] = 1
            for child in graph.get(name, []):
                if child not in graph or not visit(child):
                    return False
            colors[name] = 2
            return True

        return all(visit(name) for name in graph)

    def allowed(name, row, constraints):
        version = row['version']
        if version in blocked.get(name, []):
            return False
        if name in pins and version != pins[name]:
            return False
        return all(low <= version <= high for low, high in constraints.get(name, []))

    def search(assignment, constraints):
        nonlocal best_vector, best_versions

        if best_vector is not None:
            upper = []
            for name in names:
                if name in assignment:
                    upper.append(assignment[name]['version'])
                else:
                    possible = [row['version'] for row in packages[name]]
                    upper.append(max([-1] + possible))
            if tuple(upper) <= best_vector:
                return

        pending = [name for name in constraints if name not in assignment]
        if not pending:
            if not acyclic(assignment):
                return
            versions = {name: row['version'] for name, row in assignment.items()}
            vector = tuple(versions.get(name, -1) for name in names)
            if best_vector is None or vector > best_vector:
                best_vector = vector
                best_versions = versions
            return

        name = min(pending)
        rows = sorted(packages.get(name, []), key=lambda row: row['version'], reverse=True)
        for row in rows:
            if not allowed(name, row, constraints):
                continue
            next_assignment = assignment.copy()
            next_assignment[name] = row
            next_constraints = {key: value[:] for key, value in constraints.items()}
            viable = True
            for dep in active_deps(row):
                child = dep['name']
                interval = (dep['min'], dep['max'])
                next_constraints.setdefault(child, []).append(interval)
                if child in next_assignment and not allowed(
                    child, next_assignment[child], next_constraints
                ):
                    viable = False
                    break
            if viable:
                search(next_assignment, next_constraints)

    initial_constraints = {
        name: [(interval[0], interval[1])]
        for name, interval in roots.items()
    }
    search({}, initial_constraints)
    if best_versions is None:
        return {'error': 'unsatisfiable'}
    return {'versions': best_versions}

