def resolve(data):
    packages = data.get('packages', {})
    names = sorted(packages)
    roots = data.get('roots', {})
    blocked = data.get('blocked', {})
    pins = data.get('pins', {})
    features = set(data.get('features', []))

    # Constraints are accumulated as inclusive intervals for each required package.
    constraints = {name: [tuple(interval)] for name, interval in roots.items()}
    required = set(roots)
    best_vector = None
    best_versions = None

    def is_acyclic(edges):
        state = {}

        def visit(name):
            mark = state.get(name, 0)
            if mark == 1:
                return False
            if mark == 2:
                return True
            state[name] = 1
            for target in edges.get(name, ()):
                if not visit(target):
                    return False
            state[name] = 2
            return True

        return all(visit(name) for name in edges)

    def search(assigned, edges, needed, limits):
        nonlocal best_vector, best_versions
        pending = sorted(needed - assigned.keys())
        if not pending:
            if not is_acyclic(edges):
                return
            versions = {name: row['version'] for name, row in assigned.items()}
            vector = tuple(versions.get(name, -1) for name in names)
            if best_vector is None or vector > best_vector:
                best_vector = vector
                best_versions = versions
            return

        name = pending[0]
        rows = packages.get(name, [])
        intervals = limits.get(name, ())
        forbidden = set(blocked.get(name, ()))
        pin_present = name in pins
        choices = [
            row for row in rows
            if row['version'] not in forbidden
            and (not pin_present or row['version'] == pins[name])
            and all(low <= row['version'] <= high for low, high in intervals)
        ]
        choices.sort(key=lambda row: row['version'], reverse=True)

        for row in choices:
            version = row['version']
            next_assigned = dict(assigned)
            next_assigned[name] = row
            next_edges = dict(edges)
            active = []
            next_needed = set(needed)
            next_limits = {key: list(value) for key, value in limits.items()}
            valid = True
            for dep in row.get('deps', []):
                feature = dep.get('feature', '')
                if feature and feature not in features:
                    continue
                target = dep['name']
                low, high = dep['min'], dep['max']
                if low > high:
                    valid = False
                    break
                active.append(target)
                next_needed.add(target)
                next_limits.setdefault(target, []).append((low, high))
                selected = next_assigned.get(target)
                if selected is not None and not low <= selected['version'] <= high:
                    valid = False
                    break
            if not valid:
                continue
            next_edges[name] = active
            search(next_assigned, next_edges, next_needed, next_limits)

    search({}, {}, required, constraints)
    if best_versions is None:
        return {'error': 'unsatisfiable'}
    return {'versions': best_versions}

